class BIT():
    def __init__(self,n,mod=0):
        self.BIT = [0]*(n+1)
        self.num = n

    """
    return A[1] + A[2] + ... A[idx] in O(log n)
    """
    def query(self,idx):
        res_sum = 0
        while idx > 0:
            res_sum += self.BIT[idx]
            idx -= idx&(-idx)
        return res_sum

    """
    A[idx] += in O(log n)
    """
    def update(self,idx,x):
        while idx <= self.num:
            self.BIT[idx] += x
            idx += idx&(-idx)
        return

mod = 998244353

def calc_inv(A):
    val_set = sorted(set(A))
    comp = {e:i for i,e in enumerate(val_set)}
    A = [comp[a]+1 for a in A]

    fw = BIT(len(comp))
    res = 0
    for i in range(len(A)):
        res += i - fw.query(A[i])
        fw.update(A[i],1)
    return res


def sub_sub_solve(E,M):
    res = 0
    S = sum(E) % mod
    N = len(E)
    for i in range(len(E)):
        res += E[i] * (i-(N-1-i))
        res %= mod

    res += pow(2,M,mod) * calc_inv(E) % mod
    res %= mod
    return res


def sub_solve(N,M,A_list):
    Z_hash = [random.randint(0,2**60-1) for bit in range(M)]

