                e |= t
                for j in range(t,M)[::-1]:
                    A[j] ^= A[j-t]
                #assert A[t] == 0

        a_hash = 0
        for i in range(M):
            if A[i]:
                a_hash ^= Z_hash[i]
        if a_hash not in dic:
            dic[a_hash] = []
        dic[a_hash].append(e)

    res = 0
    for a_hash in dic:
        res += sub_sub_solve(dic[a_hash],K)
        res %= mod

    #print(K,M,A_list,res,dic)

    return res


def solve(N,M,A_list):
    minimum_deg = [[] for i in range(M)]
    for A in A_list:
        for d in range(M):
            if A[d]:
                minimum_deg[d].append(A[d:])
                break

    res = 0
    for d in range(M):
        if minimum_deg[d]:
            res += sub_solve(len(minimum_deg[d]),M-d,minimum_deg[d])
            res %= mod

    return res

