public class Main {
    static int[] p;
    static ArrayList<Integer>[] t;
    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw=new BufferedWriter(new OutputStreamWriter(System.out));
        String[] nq=br.readLine().split(" ");
        int n=Integer.parseInt(nq[0]), q=Integer.parseInt(nq[1]);
        p=new int[n+1];
        t=new ArrayList[n+1];
        for(int i=1;i<=n;i++){p[i]=i; t[i]=new ArrayList<>(); t[i].add(i);}
        for(int i=0;i<q;i++){
            String[] s=br.readLine().split(" ");
            if(s[0].equals("1")){
                int u=Integer.parseInt(s[1]), v=Integer.parseInt(s[2]);
                union(u, v);
            }
            else{
                int v=Integer.parseInt(s[1]), k=Integer.parseInt(s[2]);
                int r=find(v);
                if(t[r].size()>=k) bw.write(t[r].get(k-1)+"\n");
                else bw.write("-1\n");
            }
        }
        bw.flush();
    }
    static int find(int x){
        return p[x]==x?x:(p[x]=find(p[x]));
    }
    static void union(int x, int y){
        int fx=find(x), fy=find(y);
        if(fx==fy)return;
        if(t[fx].size() < t[fy].size()){
            int tmp=fx; fx=fy; fy=tmp;
        }
        p[fy]=fx;
        ArrayList<Integer> a=t[fx], b=t[fy];
        ArrayList<Integer> merged=new ArrayList<>();
        int ia=0, ib=0;
        while(merged.size()<10 && ia<a.size() && ib<b.size()){
            if(a.get(ia) > b.get(ib)) {merged.add(a.get(ia++));}
            else {merged.add(b.get(ib++));}
        }
        while(merged.size()<10 && ia<a.size()) merged.add(a.get(ia++));
        while(merged.size()<10 && ib<b.size()) merged.add(b.get(ib++));
        t[fx]=merged;
    }
}

