    public static void main(String[] args) {
        sc = new Scanner(System.in);
        out = new PrintWriter(System.out);
        new Main().solve();
        out.flush();
    }

    long mod = 998244353;
    TreeSet<Integer> set = new TreeSet<>();
    int [][] memo;
    int n;
    List<Integer>[] next;
    int[] ceil;
    int w;
    int[] wmap;

    public void solve() {
        n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        boolean[] v = new boolean[n];
        if(m==0) {
            out.println(1);
            return;
        }
        next = new List[n];
        for(int i=0; i<n; i++) {
            next[i] = new ArrayList<>();
        }

        for(int i=0; i<m; i++) {
            int a = sc.nextInt()-1;
            int b = sc.nextInt()-1;
            next[a].add(b);
            set.add(a);
            v[a] = true;
        }
        //set.add(set.first() + n);
        ceil = new int[n];
        int first = set.first();
        for(int i=n-1; i>=0; i--) {
            if(v[i]) {
                first = i;
            }
            ceil[i] = first;
        }

        w = set.size();
        wmap = new int[n];
        int p = 0;
        for(int x : set) {
            wmap[x] = p;
            p++;
        }
        memo = new int[m][k+1];
        for(int[] a : memo) {
            Arrays.fill(a, -1);
        }


        out.println(calc(0, k));

    }

    int calc(int pos, int k) {
        if(k==0) {
            return 1;
        }
        int npos = ceil[pos];
        int d = npos - pos;
        if(d<0) {
            d += n;
        }
        if(k <= d) {
            return 1;
        }
        pos = npos % n;
        k -= d;

        int wi = wmap[pos];

        if(memo[wi][k] != -1) {
            return memo[wi][k];
        }
        long sum = calc((pos + 1) % n, k-1);
        for(int np : next[pos]) {
            sum += calc(np, k-1);
            sum %= mod;
        }
        return memo[wi][k] = (int)sum;

    }

}

