	double[] p, q, r, dp;

	void calc() {
		int[] ns = nextInts();
		N = ns[0]; L = ns[1]; D = ns[2];
		int NN = Math.max(N + 2, L + D + 1);
		p = new double[NN];
		p[0] = 1;
		dp = new double[NN];
		dp[1] = -1;
		for (int i = 0; i < NN - 1; i++) {
			if (i < L) {
				dp[i + 1] += p[i] / D;
				dp[i + D + 1] -= p[i] / D;
			}
			p[i+1] = p[i] + dp[i+1];
		}
		for (int i = N + 2; i < NN; i++) {
			p[N + 1] += p[i]; p[i] = 0;
		}

		q = new double[N + 1];
		double ap = p[N+1];
		for (int i = 0; i < L; i++) q[i] = p[N+1];
		for (int i = L; i <= N; i++) {
