			b <<= 1;
		}
		int n2 = b * 2 - 1;
		list = new ArrayList<>(n2);
		for (int i = 0; i < n2; i++) {
			MultiTreeSet<Integer> set = new MultiTreeSet<>();
			set.add(0);
			list.add(set);
		}
		for (int i = 0; i < n; i++) {
