			}
		}
		pw.flush();
		br.close();
	}

	static int get(int i) {
		i += b - 1;
		int ret = list.get(i).last();
		while (i > 0) {
			i = (i - 1) / 2;
			ret = Math.max(ret, list.get(i).last());
		}
		return ret;
	}

	static void add(int l, int r, int x) {
		update(l, r, 0, 0, b, x, true);
	}

