		}

		T ceiling(T e) {
			return map.ceilingKey(e);
		}

		T first() {
			return map.firstKey();
		}

		T last() {
			return map.lastKey();
		}

		T pollFirst() {
			T e = map.firstKey();
			remove(e);
			return e;
		}

		T pollLast() {
			T e = map.lastKey();
			remove(e);
			return e;
		}

		List<T> toListUnq() {
