def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def count_divisible_numbers(n, m, limit):
    lcm_value = lcm(n, m)
    divisible_by_n = limit // n
    divisible_by_m = limit // m
    divisible_by_lcm = limit // lcm_value
    return divisible_by_n + divisible_by_m - 2 * divisible_by_lcm

def kth_smallest_divisible(N, M, K):
    low = 1
    high = 10**18

    while low < high:
        mid = (low + high) // 2
        count = count_divisible_numbers(N, M, mid)
        if count < K:
            low = mid + 1
        else:
            high = mid

    return low

