import java.io.PrintWriter;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        var sc = new Scanner(System.in);

        int n = Integer.parseInt(sc.next());
        int m = Integer.parseInt(sc.next());
        var a = new int[n+1];
        for(int i = 1; i <= n; i++){
            a[i] = Integer.parseInt(sc.next());
        }
        var b = new int[m];
        for(int i = 0; i < m; i++){
            b[i] = Integer.parseInt(sc.next()) + 1;
        }

        var bit = new BinaryIndexedTree(n);
        for(int i = 1; i <= n; i++){
            bit.add(i, i+1, a[i]);
        }

        for(int i = 0; i < m; i++){
            long value = bit.sum(b[i], b[i]+1);
            bit.add(b[i], b[i]+1, -value);
            if(value >= n){
                bit.add(1, n+1, value / n);
                value %= n;
            }

            if(value > 0 && b[i] < n){
                bit.add(b[i]+1, (int) Math.min(b[i]+1 + value, n+1), 1);
                value -= Math.min(value, n - b[i]);
            }

            if(value > 0){
                bit.add(1, (int) (value+1), 1);
            }
        }

        var pw = new PrintWriter(System.out);
        for(int i = 1; i <= n; i++){
            if(i < n){
                pw.print(bit.sum(i, i+1) + " ");
            }else{
                pw.println(bit.sum(i, i+1));
            }
        }
        pw.flush();
    }

    static class BinaryIndexedTree {
        int n;
        long[] p, q;

        public BinaryIndexedTree(int n){
            this.n = n;
            p = new long[n+1];
            q = new long[n+1];
        }
        void add(int l, int r, long x){
            add(p, l, -x*(l-1));
            add(p, r, x*(r-1));
            add(q, l, x);
            add(q, r, -x);
        }
        void add(long[] bit, int i, long x){
            while(i <= n){
                bit[i] += x;
                i += i & -i;
            }
        }
        long sum(int l, int r){
            return sum(r-1) - sum(l-1);
        }
        long sum(int i){
            return sum(p, i) + sum(q, i)*i;
        }
        long sum(long[] bit, int i){
            long s = 0;
            while(i > 0){
                s += bit[i];
                i -= i & -i;
            }
            return s;
        }
    }
}

