def solve(n, r, p):
    if n < r:
        return False
    # 奇数の場合
    if n % 2 == 1:
        if r <= (n - 1) // 2:
            p_max = (n - r) * (n + 1) // 2
            # print(f"n={n},r={r},p={p},p_max={p_max}")
            if p <= p_max:
                return True
            else:
                return False
        else:
            I = r - (n - 1) // 2
            p_max = ((n+1) // 2) ** 2
            for i in range(I):
                p_max -= (((n-2*i) - (n-1-2*i)//2) * 2 - 1)
            # print(f"n={n},r={r},p={p},p_max={p_max}")
            if p <= p_max:
                return True
            else:
                return False
    else:
        if r == 0:
            p_max = n * n // 2
            # print(f"n={n},r={r},p={p},p_max={p_max}")
            if p <= p_max:
                return True
            else:
                return False
        else:
            return solve(n-1, r-1, p)




