import java.io.*;

import java.math.*;



public class Main{

    public static void main(String[] args) throws Exception {

        new Solution().SOLVE();

    }

}



class Solution {

    Read sc = new Read();





    public void SOLVE() throws IOException {

        int T = 1;

        while (T-- > 0) {

            solve();

        }

        sc.bw.flush();

        sc.bw.close();

    }



    void solve() throws IOException {

        int n = sc.nextInt();

        long[] pre = new long[n + 1];

        long min = 0;

        for (int i = 1; i <= n; i++) {

            pre[i] = sc.nextInt();

            pre[i] += pre[i - 1];

            min = Math.min(min, pre[i]);

        }

        sc.println(pre[n] - min);

    }



    private int gcd (int a, int b) {

        if (b == 0) return a;

        return gcd(b, a % b);

    }



    public long qmi(long a, int k, int p){

        long res = 1;

        while(k > 0){

            if( (k & 1) != 0 ) res = res * a % p;

            long t = a * a;

            a = t % p;

            k >>= 1;

        }

        return res;

    }

}



