public class Main {

    static int[] lefts;

    static int[] rights;

    static int[] dp;

    public static void main(String[] args) throws Exception {

        Scanner sc = new Scanner();

        int n = sc.nextInt();

        int d = sc.nextInt();

        SegmentTree st = new SegmentTree(500000);

        lefts = new int[n + 1];

        rights = new int[n + 1];

        for (int i = 1; i <= n; i++) {

            int x = sc.nextInt() - 1;

            lefts[i] = st.getMax(x - d, x);

            rights[i] = st.getMax(x, x + d + 1);

            st.setValue(x, i);

        }

        dp = new int[n + 1];

        int ans = 0;

        for (int i = 0; i <= n; i++) {

            ans = Math.max(ans, dfw(i));

        }

        System.out.println(ans);

    }



    static int dfw(int idx) {

        if (idx == 0) {

            return 0;

        }

        if (dp[idx] == 0) {

            dp[idx] = Math.max(dfw(lefts[idx]), dfw(rights[idx])) + 1;

        }

        return dp[idx];

    }



    static class SegmentTree {

        int size;

        int[] values;



        public SegmentTree(int x) {

            size = 2;

            while (size < x) {

                size <<= 1;

            }

            values = new int[size * 2 - 1];

        }



        public void setValue(int idx, int v) {

            int current = idx + size - 1;

            values[current] = v;

            calc((current - 1) / 2);

        }



        private void calc(int idx) {

            values[idx] = Math.max(values[idx * 2 + 1], values[idx * 2 + 2]);

            if (idx > 0) {

                calc((idx - 1) / 2);

            }

        }



        public int getMax(int left, int right) {

            return getMax(0, 0, size, left, right);

        }



        private int getMax(int idx, int min, int max, int left, int right) {

            if (max <= left || right <= min) {

                return 0;

            } else if (left <= min && max <= right) {

                return values[idx];

            } else {

                return Math.max(getMax(idx * 2 + 1, min, (min + max) / 2, left, right)

                    , getMax(idx * 2 + 2, (min + max) / 2, max, left, right));

            }

        }

    }

}



