import java.util.ArrayList;

import java.util.List;

import java.util.Scanner;



public class Main {



	static final int MSTSZ = 262144;

	static long soll, solr;

	static long solx;



	public static void main(String[] args) {

		try(Scanner sc = new Scanner(System.in);) {

			int n = Integer.parseInt(sc.next());

			List<Long> a = new ArrayList<Long>();

			for(int i = 0; i < n; i++) a.add(Long.parseLong(sc.next()));

			final long big = 2000000000;

			while(a.size() < MSTSZ) {a.add(big);}



			List<List<Long>> mst = new ArrayList<List<Long>>();

			for(int i = 0; i < 2 * MSTSZ; i++) mst.add(new ArrayList<Long>());



			for(int i = 0; i < MSTSZ; i++){

				mst.get(MSTSZ - 1 + i).add(a.get(i));

			}



			for(int i = MSTSZ - 2; i >= 0; i--) {

				mst.set(i, merge(mst.get(2 * i + 1), mst.get(2 * i + 2)));

			}



			List<List<Long>> sum = new ArrayList<List<Long>>();

			for(int i = 0; i < mst.size(); i++) sum.add(new ArrayList<Long>(mst.get(i)));

			for(List<Long> nx : sum) {

				int l = nx.size();

				for(int i = 1; i < l; i++) {

					long v = nx.get(i - 1);

					nx.set(i, nx.get(i) + v);

				}

			}



			int q = Integer.parseInt(sc.next());

			long b = 0;

			StringBuilder sb = new StringBuilder();

			while(q > 0) {

				q--;

				long alp = Long.parseLong(sc.next());

				long bet = Long.parseLong(sc.next());

				long gam = Long.parseLong(sc.next());



				long l = (alp ^ b);

				long r = (bet ^ b);

				long x = (gam ^ b);



				soll = l - 1;

				solr = r - 1;

				solx = x;

				b = solve(0, MSTSZ, 0, mst, sum);

				sb.append(b).append("\n");

			}



			System.out.print(sb.toString());

		}

	}



	static List<Long> merge(List<Long> l, List<Long> r){

		List<Long> res = new ArrayList<Long>();



		int lp = 0, rp = 0;

		while(lp < l.size() || rp < r.size()) {

			if(lp == l.size()) {res.add(r.get(rp)); rp++;}

			else if(rp == r.size()) {res.add(l.get(lp)); lp++;}

			else if(l.get(lp) < r.get(rp)) {res.add(l.get(lp)); lp++;}

			else {res.add(r.get(rp)); rp++;}

		}



		return res;

	}



	static long solve(int l, int r, int id, List<List<Long>> mst, List<List<Long>> sum) {

		if(l >= r) {return 0;}

		if(solr < l) {return 0;}

		if((r - 1) < soll) {return 0;}



		if(soll <= l && (r - 1) <= solr) {

			int nl = 0, nr = mst.get(id).size() - 1; 

			while(nl <= nr) {

				int te = (nl + nr) / 2;

				if(mst.get(id).get(te) <= solx) {nl = te + 1;}

				else {nr = te - 1;};

			}

			if(nr >= 0) {return sum.get(id).get(nr);}

			return 0;

		}



		long up = 0;

		up += solve(l, (l + r) / 2, 2 * id + 1, mst, sum);

		up += solve((l + r) / 2, r, 2 * id + 2, mst, sum);

		return up;

	}

}

