import java.util.*;



public class Main {

    //区间交叉问题

    //每个区间都异或一个随机值，如果当前区间的两个端点的 xor 值不同了，就说明有区间交叉了

    static class Tree {

        int l, r;

        long lazy;//区间和，懒标记

        long xor;

    }



    static void init(int n) {

        int len = 4 * n;

        tr = new Tree[len];

        for (int i = 0; i < len; i++) {

            tr[i] = new Tree();

        }

        build(1, 0, n - 1);//默认根节点编号为 1，区间左端点为 0 ，右端点为 n - 1

    }



    static void build(int u, int l, int r) {

        tr[u].l = l;

        tr[u].r = r;

        if (l == r) return;

        int mid = l + r >> 1;

        build(u << 1, l, mid);

        build(u << 1 | 1, mid + 1, r);

        //pushUp(u);

    }





    //子节点信息更新父节点信息

    static void pushUp(int u) {

        tr[u].xor = tr[u << 1].xor ^ tr[u << 1 | 1].xor;

    }



    //下传懒标记

    static void pushDown(int u) {

        if (tr[u].lazy == 0) return;

        pd(u << 1, tr[u].lazy);

        pd(u << 1 | 1, tr[u].lazy);

        tr[u].lazy = 0;

    }



    static void pd(int u, long lazy) {

        tr[u].lazy ^= lazy;

        tr[u].xor ^= lazy;

    }



    //区间修改 区间 + v

    static void updateRange(int u, int l, int r, long v) {

        if (l <= tr[u].l && tr[u].r <= r) {//完全覆盖

            pd(u, v);

            return;

        }

        pushDown(u);

        int mid = tr[u].l + tr[u].r >> 1;

        if (mid >= l) updateRange(u << 1, l, r, v);

        if (mid < r) updateRange(u << 1 | 1, l, r, v);

        //  pushUp(u);

    }





    //单点查询

    static long querySingle(int u, int x) {

        if (tr[u].l == x && tr[u].r == x) return tr[u].xor;

        pushDown(u);

        int mid = tr[u].l + tr[u].r >> 1;



        if (mid >= x) return querySingle(u << 1, x);

        else return querySingle(u << 1 | 1, x);

    }





    static Tree[] tr;



    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        init(n * 2);

        Random random = new Random();

        for (int i = 0; i < n; i++) {

            int l = sc.nextInt() - 1, r = sc.nextInt() - 1;

            if (l > r) {

                int t = l;

                l = r;

                r = t;

            }

            long v1 = querySingle(1, l), v2 = querySingle(1, r);

            if (v1 != v2) {

                System.out.println("Yes");

                return;

            }

            long d = random.nextLong();

            updateRange(1, l, r, d);

        }

        System.out.println("No");

    }





}

