    final int N = sc.nextInt();

    final int M = sc.nextInt();

    final int[] X = new int[M];

    for (int i = 0; i < M; i++) {

      X[i] = sc.nextInt() - 1;

    }



    final long[] v = new long[2*N];

    for (int i = 1; i < M; i++){

      int l = Math.min(X[i-1], X[i]);

      int r = Math.max(X[i-1], X[i]);

      int d0 = r - l;

      int d1 = N - d0;

      if (d0 == d1) { continue; }

      long diff = Math.abs(d0 - d1);

      if (d0 < d1) {

        v[l] += diff;

        v[r] -= diff;

      } else {

        v[r] += diff;

        v[l+N] -= diff;

      }

    }



    // 累積和

    for (int i = 1; i < 2*N; i++) {

      v[i] += v[i-1];

    }



    // decide deletion

    int del = -1;

    long minp = (1L << 60);

    for (int i = 0; i < N; i++) {

      long penalty = v[i] + v[i+N];

      if (penalty < minp) {

        del = i;

        minp = penalty;

      }

    }



    // solve len

    long len = 0;

    for (int i = 1; i < M; i++){

      int l = Math.min(X[i-1], X[i]);

      int r = Math.max(X[i-1], X[i]);

      int d0 = r - l;

      int d1 = N - d0;

      if (del >= l && del < r){

        len += d1;

      } else {

        len += d0;

      }

    }



    out.println(len);

  }

}





