		int n2 = n * 2;

		int[] c = new int[n2];

		for (int i = 0; i < n; i++) {

			c[i] = sc.nextInt() - 1;

			c[i + n] = c[i];

		}

		sc.close();



		int[] total = new int[n];

		for (int i = 0; i < n; i++) {

			total[c[i]]++;

		}



		int[] cnt = new int[n];

		int b = 0;

		int r = n - 1;

		for (int i = 0; i < n; i++) {

			cnt[c[i]]++;

			if (k == 1 || cnt[c[i]] % k == 1) {

				b++;

