					r = i;

					break;

				}

			}

		}



		int[] num = new int[n + 1];

		for (int i = 0; i < num.length; i++) {

			num[i] = (i + k - 1) / k * k;

		}



		int val = 0;

		for (int i = 0; i < n; i++) {

			val += Math.min(num[cnt[i]], total[i]);

		}

