		PrintWriter pw = new PrintWriter(System.out);
		for (int z = 0; z < t; z++) {
			String[] sa = br.readLine().split(" ");
			int n = Integer.parseInt(sa[0]);
			int m = Integer.parseInt(sa[1]);
			PriorityQueue<Obj> que = new PriorityQueue<>((o1, o2) -> o1.p - o2.p);
			for (int i = 0; i < n; i++) {
				sa = br.readLine().split(" ");
				Obj o = new Obj();
				o.v = Integer.parseInt(sa[0]);
				o.p = Integer.parseInt(sa[1]);
				que.add(o);
			}

			long ans = 0;
			long val = 0;
			PriorityQueue<Obj> que2 = new PriorityQueue<>((o1, o2) -> o1.v - o2.v);
			while (!que.isEmpty()) {
				Obj o = que.poll();
				if (o.v <= o.p) {
