class factorial():
    def __init__(self,mod=998244353):
        self.mod=mod
        self.fact_n=[1]
        self.fact_i=[1]
        self.fact_l=0

    def create(self,n):
        if self.fact_l<n:
            nn=(n//4096+1)*4096
            for i in range(self.fact_l+1,nn+1):
                self.fact_n.append((self.fact_n[-1]*i)%self.mod)
                self.fact_i.append(0)
            self.fact_i[nn]=pow(self.fact_n[nn],-1,self.mod)
            for i in range(nn,self.fact_l+1,-1):
                self.fact_i[i-1]=(self.fact_i[i]*i)%self.mod
            self.fact_l=nn

    def fact(self,n):
        assert n>=0
        if n>self.fact_l:
            self.create(n)
        return self.fact_n[n]

    def fact_inv(self,n):
        assert n>=0
        if n>self.fact_l:
            self.create(n)
        return self.fact_i[n]

    def perm(self,n,r):
        if r<0:
            return 0
        if n>=0:
            if n<r:
                return 0
            return (self.fact(n)*self.fact_inv(n-r))%self.mod
        elif n<0:
            ret=(self.fact(-n+r-1)*self.fact_inv(-n-1))%self.mod
            if r%2==1:
                ret=-ret
                ret%=self.mod
            return ret

    def comb(self,n,r):
        if r<0:
            return 0
        if n>=0:
            if n<r:
                return 0
            return (self.fact(n)*self.fact_inv(n-r)*self.fact_inv(r))%self.mod
        elif n<0:
            ret=(self.fact(-n+r-1)*self.fact_inv(-n-1)*self.fact_inv(r))%self.mod
            if r%2==1:
                ret=-ret
                ret%=self.mod
            return ret

