        Set<Long> set1=new HashSet<>(),set2=new HashSet<>(),set3=new HashSet<>(),set4=new HashSet<>(),set5=new HashSet<>();
        for(int i=0;i<m;i++){
            long a=sc.nextInt(),b=sc.nextInt();
            set1.add(a);
            set2.add(b);
            set3.add(a+b);
            set4.add(a-b);
        }
        long ans=(n-set1.size())*(long)(n-set2.size());
        //加入主对角线：
        for(long a:set3){
            set5=new HashSet<>();
            //x+y==a,1<=x<=n,1<=a-x<=n
            for(long b:set1){
                if(a-b>=1&&a-b<=n){
                    set5.add((b<<31)+a-b);
                }
            }
            for(long b:set2){
                if(a-b>=1&&a-b<=n){
                    set5.add(((a-b)<<31)+b);
                }
            }
            ans-=1+Math.min(a-1,n)-Math.max(1,a-n)-set5.size();
        }
