public class Main {
    public static void main(String[] args) {
        int n = sc.nextInt();
        long k = sc.nextLong();

        int[] a = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            a[i] = sc.nextInt();
        }
        int m = 60;
        int[][] fa = new int[m][n + 1];
        for (int i = 1; i <= n; i++) {
            fa[0][a[i]] = a[a[i]];
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j <= n; j++) {
                fa[i][a[j]] = fa[i - 1][fa[i - 1][a[j]]];
            }
        }

        int[] ans = new int[n + 1];
        boolean[] vis = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            if (!vis[i]) {
                List<Integer> l = new ArrayList<>();
                int z = i;
                while (!vis[z]) {
                    l.add(z);
                    vis[z] = true;
                    z = fa[0][z];
                }
                int mod = l.size();
                long kk = pow(2, k , mod);

                for (int u : l) {
                    int v = u;
                    for (int j = 0; j < 60; j++) {
                        if ((kk >> j & 1) == 1) u = fa[j][u];
                    }
                    ans[v] = u;
                }

            }

        }
        for (int i = 1; i <= n; i++) {
            out.print(ans[i] + " ");
        }


        out.close();
    }


    static long pow(long x, long n, int mod) {
        if (n == 0) return 1;
        if (n % 2 == 0) return pow(x * x % mod, n / 2, mod);
        else return pow(x * x % mod, n / 2, mod) * x % mod;
    }


