import java.util.ArrayList;

import java.util.LinkedList;

import java.util.Queue;

import java.util.Scanner;



public class Main {

    static int N;

    static int M;



    static ArrayList<ArrayList<Integer>> adj = new ArrayList<>();



    static class Pair {

        public int node;

        public int count;



        Pair(int node, int count) {

            this.node = node;

            this.count = count;

        }

    }



    static boolean[] visited;



    static int bfs() {



        Queue<Pair> q = new LinkedList<>();

        for (int temp : adj.get(1)) q.offer(new Pair(temp, 0));



        while (!q.isEmpty()) {

            Pair p = q.poll();

            if (visited[p.node]) continue;

            else visited[p.node] = true;

            if (p.node == 1) return p.count + 1;

            for (int temp : adj.get(p.node)) q.offer(new Pair(temp, p.count + 1));

        }



        return -1;



    }





    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        N = sc.nextInt();

        M = sc.nextInt();

        for (int i = 0; i <= N; i++) adj.add(new ArrayList<>());

        visited = new boolean[N + 1];



        int a, b;

        for (int i = 1; i <= M; i++) {

            a = sc.nextInt();

            b = sc.nextInt();

            adj.get(a).add(b);

        }



        System.out.println(bfs());

    }



}

