import java.util.ArrayList;

import java.util.Collections;

import java.util.PriorityQueue;

import java.util.Scanner;

import java.util.stream.IntStream;



public class Main {

	public static void main(String[] args) {

		var sc = new Scanner(System.in);

		var t = sc.nextInt();

		var n = new int[t];

		var k = new int[t];

		var a = new int[t][];

		var b = new int[t][];

		for (var i = 0; i < t; i++) {

			n[i] = sc.nextInt();

			k[i] = sc.nextInt();

			a[i] = IntStream.range(0, n[i]).map(x -> sc.nextInt()).toArray();

			b[i] = IntStream.range(0, n[i]).map(x -> sc.nextInt()).toArray();

		}

		sc.close();



		var sb = new StringBuilder();

		for (var i = 0; i < t; i++) {

			var result = calc(n[i], k[i], a[i], b[i]);

			sb.append(result);

			sb.append("\r\n");

		}

		System.out.println(sb.toString());

	}



	private static long calc(int n, int k, int[] a, int[] b) {

		var result = Long.MAX_VALUE;

		var items1 = new ArrayList<Item1>();

		for (var i = 0; i < n; i++) {

			items1.add(new Main().new Item1(a[i], b[i]));

		}

		Collections.sort(items1);

//		for (var i = 0; i < n; i++) {

//			System.out.printf("%d %d\r\n", items1.get(i).key, items1.get(i).value);

//		}



		var sum = 0L;

		var pq = new PriorityQueue<Integer>();

		for (var i = 0; i < k; i++) {

			sum += items1.get(i).value;

			pq.add(-items1.get(i).value);

		}



		for (var i = k - 1; i < n; i++) {

			var key = (long)items1.get(i).key;

			var value = items1.get(i).value;

			if (i >= k) {

				var v1 = -pq.peek();

				if (v1 >= value) {

					pq.poll();

					pq.add(-value);

					sum -=  v1 - value;

				}

			}

			var max = key;

			var v = max * sum;

			//System.out.printf("%d %d %d %d %d\r\n", i, key, value, sum, v);

			result = Math.min(result, v);

		}



		return result;

	}



	public class Item1 implements Comparable<Item1> {

		private int key;

		private int value;



		public Item1(int key, int value) {

			this.key = key;

			this.value = value;

		}



		@Override

		public int compareTo(Item1 target) {

			if (this.key - target.key > 0) {

				return 1;

			} else if (this.key - target.key < 0) {

				return -1;

			}

			if (this.value - target.value > 0) {

				return 1;

			} else if (this.value - target.value < 0) {

				return -1;

			}

			return 0;

		}

	}

}

