    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);



        // Input for n, s, t

        n = sc.nextInt();

        s = sc.nextInt();

        t = sc.nextInt();



        pointsDist = new double[n]; 





        for (int i = 0; i < n; i++) {

            int a = sc.nextInt();

            int b = sc.nextInt();

            int c = sc.nextInt();

            int d = sc.nextInt();



            points.add(new int[][] {{a, b}, {c, d}});

            pointsDist[i] = getDistance(a, b, c, d);

        }





        solver(0, 0, new int[] {0, 0}, new ArrayList<>());



        System.out.println(ans);

    }





    static double getDistance(int x1, int y1, int x2, int y2) {

        return Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));

    }





    static void solver(double move, double lazer, int[] point, List<Integer> passed) {

        for (int i = 0; i < n; i++) {

            if (passed.contains(i)) {

                continue;

            } else {

                for (int j = 0; j < 2; j++) {

                    int[] nextPoint = points.get(i)[j];

