                    double newLazer = lazer + pointsDist[i];

                    List<Integer> newPassed = new ArrayList<>(passed);

                    newPassed.add(i);



                    if (newPassed.size() == n) {

                        ans = Math.min(ans, newMove / s + newLazer / t);

                    } else {

                        solver(newMove, newLazer, points.get(i)[1 - j], newPassed);

                    }

                }

            }

        }

    }

}

