public class Main {

	public static void main(String[] args) {

		var sc = new Scanner(System.in);

		var n = sc.nextInt();

		var x = sc.nextInt();

		var a = new int[n];

		var b = new int[n];

		var c = new int[n];

		var d = new int[n];

		for (var i = 0; i < n; i++) {

			a[i] = sc.nextInt();

			b[i] = sc.nextInt();

			c[i] = sc.nextInt();

			d[i] = sc.nextInt();

		}

