		var bs = new Main().new BinSearch(n, x, a, b, c, d);

		var result = bs.search();

		System.out.println(result);

	}



	public class BinSearch {

		private int n;

		private int x;

		private int[] a;

		private int[] b;

		private int[] c;

		private int[] d;



		public BinSearch(int n, int x, int[] a, int[] b, int[] c, int[] d) {

