			this.c = c;

			this.d = d;

		}



		public long search() {

			return search1((long)0, (long)1000000000);

		}



		public long search1(long min, long max) {

			while (max - min > 1) {

				var mid = min + (max - min) / 2;

				if (check(mid)) {

					min = mid;

				} else {

					max = mid - 1;

				}

			}

			if (check(max)) {

				return max;

			}

			return min;

		}



		public long search2(long min, long max) {

			while (max - min > 1) {

				var mid = min + (max - min) / 2;

				if (check(mid)) {

					max = mid;

				} else {

					min = mid + 1;

				}

			}

			if (check(min)) {

