        int[] A = new int[N];



        for (int i = 0; i < N; ++i) {

            A[i] = nextInt(in);

        }



        long[][] dp = new long[N][2];



        dp[0][0] = 0;

        dp[0][1] = A[0];



        for (int i = 1; i < N; ++i) {

            dp[i][0] = Math.max(dp[i - 1][1] + 2*A[i], dp[i - 1][0]);

            dp[i][1] = Math.max(dp[i - 1][0] + A[i], dp[i - 1][1]);

        }



        out.println(Math.max(dp[N - 1][0], dp[N - 1][1]));



        out.close();

        reader.close();

    }



