def deep_recursion():

  import sys

  import pypyjit  # type: ignore

  sys.setrecursionlimit(550000)

  pypyjit.set_param('max_unroll_recursion=-1')



def main():

  N = int(input())

  adj = [[] for _ in range(N)]

  for _ in range(N - 1):

    u, v, l = readints()

    u -= 1

    v -= 1

    adj[u].append((v, l))

    adj[v].append((u, l))



  def dfs(u, p):

    res = SortedList()

    for v, l in adj[u]:

      if v == p:

        continue

      cur = dfs(v, u)

      cur.add(cur.pop() + l)

      if len(res) >= len(cur):

        for x in cur:

          res.add(x)

      else:

        for x in res:

          cur.add(x)

        res = cur



    if not res:

      return SortedList([0])

    else:

      return res



  xs = dfs(0, -1)

  cur = 0

  for _ in range(N):

    if xs:

      cur += xs.pop()

