      int n = Integer.parseInt(st.nextToken());

      int m = Integer.parseInt(st.nextToken());



      StringJoiner sj = new StringJoiner(" ");

      if(n%2 == 1){

         int mid = (n+1)/2;

         for(int k = 0; k < m; k++){

            sj.add("" + mid);

         }

         if(n != 1){

            //rest is basically even

            int mid2 = mid-1;

            sj.add("" + mid2);

            for(int k = n; k >= 1; k--){

               int rep = m;

               if(k == mid2) rep--;

               if(k == mid) continue;

               for(int j = 0; j < rep; j++){

                  sj.add("" + k);

