			Obj o = new Obj();

			o.num = dp[i];

			dfs3(i, g, o.que);

			que.add(o);

		}



		int n2 = n / 2;

		PrintWriter pw = new PrintWriter(System.out);

		for (int i = 0; i < n2; i++) {

			Obj o1 = que.poll();

			Obj o2 = que.poll();

			int i1 = o1.que.poll() + 1;

			if (o2 == null) {

				int i2 = g + 1;

				pw.println(i1 + " " + i2);

				break;

			}

			int i2 = o2.que.poll() + 1;

			pw.println(i1 + " " + i2);

			o1.num--;

			o2.num--;

			if (o1.num > 0) {

				que.add(o1);

			}

			if (o2.num > 0) {

				que.add(o2);

			}

		}

		pw.flush();

	}



	static class Obj implements Comparable<Obj> {

		int num;

		Queue<Integer> que = new ArrayDeque<>();



		@Override

		public int compareTo(Obj o) {

			if (num % 2 == 1) {

				return -1;

			}

			if (o.num % 2 == 1) {

				return 1;

			}

			return o.num - num;

		}

	}



	static int dfs(int x, int p) {

		int ret = 1;

		for (int c : list.get(x)) {

