   // }

  }



  //

  init(n);

  buildST(a, 0, 0, n - 1);

  //



  int nextb[] = new int[n];

  for (int i = 0; i < n; i++) {

   b[i] = sc.nextInt();

  }

  nextb[n - 1] = n;

