class Matrix():

    def __init__(self, MOD=-1):
        self.MOD = MOD

    def mul(self, a, b):
        L, M, N = len(a), len(b), len(b[0])
        assert len(a[0]) == M
        c = [[0] * N for _ in range(L)]
        for i in range(L):
            for j in range(N):
                for k in range(M):
                    c[i][j] += a[i][k] * b[k][j]
                    if self.MOD != -1:
                        c[i][j] %= self.MOD
        return c

    def pow(self, x, n):
        y = [[0] * len(x) for _ in range(len(x))]
        for i in range(len(x)):
            y[i][i] = 1
        while n > 0:
            if n & 1:
                y = self.mul(x, y)
            x = self.mul(x, x)
            n >>= 1
        return y

