		for (char ch : c) {
			if (ch == l) {
				count++;
			}
		}
		return count;
	}

	boolean solve(char[] s, char[] x, char[] y) {
		long x0 = count(x, '0');
		long x1 = count(x, '1');
		long y0 = count(y, '0');
		long y1 = count(y, '1');

		if (x1 == y1)
			return x0 == y0;
		if (x0 == y0)
			return true;

		long sl = s.length;
		if ((sl * (y0 - x0)) % (x1 - y1) != 0)
			return false;
		long tl = (sl * (y0 - x0)) / (x1 - y1);
		if (tl < 0)
			return false;

		int d = (int) NumberTheory.gcd(sl, tl);

		for (int i = d; i < s.length; i++) {
			if (s[i] != s[i - d]) {
				return false;
			}
		}

		return true;
	}

