import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        long n = scanner.nextLong();
        long m = scanner.nextLong();

        ArrayList<Long> list = new ArrayList<>();
        for (long i = 0; i < n; i++) {
            list.add(scanner.nextLong());
        }
        list.sort((o1, o2) -> Math.toIntExact(o1 - o2));

        ArrayList<Long> preSum = new ArrayList<>();
        preSum.add(0L);
        preSum.add(list.get(0));

        for (int i = 1; i < n; i++) {
            preSum.add(list.get(i) + preSum.get(i));
        }
        long res = 0;

        long left = 0, right = list.get((int) (n - 1));
        while (left <= right) {
            long mid = (left + right) / 2;
            long total = sum(list, mid);
            if (total <= m) {
                res = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        if (res >= list.get((int) (n - 1))) {
            System.out.println("infinite");
        } else {
            System.out.println(res);
        }
    }

    private static int index(List<Long> list, Long t) {
        int left = 0, right = list.size() - 1;
        int res = 0;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (t.compareTo(list.get(mid)) >= 0) {
                res = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return res;
    }

    private static Long sum(List<Long> list, long x) {
        Long sum = 0L;
        for (int i = 0; i < list.size(); i++) {
            sum += Math.min(list.get(i), x);
        }
        return sum;
    }
}

