import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Set;
import java.util.TreeMap;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		int[] l = new int[n];
		int[] u = new int[n];
		for (int i = 0; i < n; i++) {
			String[] sa = br.readLine().split(" ");
			l[i] = Integer.parseInt(sa[0]);
			u[i] = Integer.parseInt(sa[1]);
		}
		int q = Integer.parseInt(br.readLine());
		Query[] arr = new Query[q];
		PriorityQueue<Query> que1 = new PriorityQueue<>((o1, o2) -> o1.sx - o2.sx);
		for (int i = 0; i < q; i++) {
			String[] sa = br.readLine().split(" ");
			Query o = new Query();
			o.i = i;
			o.sx = Integer.parseInt(sa[0]) - 1;
			o.sy = Integer.parseInt(sa[1]);
			o.tx = Integer.parseInt(sa[2]) - 1;
			o.ty = Integer.parseInt(sa[3]);
			if (o.sx > o.tx) {
				int t = o.sx;
				o.sx = o.tx;
				o.tx = t;
				t = o.sy;
				o.sy = o.ty;
				o.ty = t;
			}
			o.ans = o.tx - o.sx;
			arr[i] = o;
			que1.add(o);
		}
		br.close();

		PriorityQueue<Query> que2 = new PriorityQueue<>((o1, o2) -> o1.tx - o2.tx);
		TreeMap<Integer, Obj> map = new TreeMap<>();
		for (int i = 0; i < n; i++) {
			Map<Integer, Obj> hm = map.headMap(l[i]);
			Integer[] ks = hm.keySet().toArray(new Integer[0]);
			for (Integer k : ks) {
				Obj o = hm.get(k);
				o.cost += l[i] - k;
				o.y = l[i];
				if (map.containsKey(l[i])) {
					Obj o1 = o;
					Obj o2 = map.get(l[i]);
					if (o1.set.size() > o2.set.size()) {
						o1 = o2;
						o2 = o;
						map.put(l[i], o);
					}
					for (int e : o1.set) {
						Query qr = arr[e];
						qr.ans += o1.cost - qr.oc;
						qr.oc = o2.cost;
						qr.o = o2;
					}
					o2.set.addAll(o1.set);
				} else {
					map.put(l[i], o);
				}
			}
			hm.clear();

			Map<Integer, Obj> tm = map.tailMap(u[i] + 1);
			ks = tm.keySet().toArray(new Integer[0]);
			for (Integer k : ks) {
				Obj o = tm.get(k);
				o.cost += k - u[i];
				o.y = u[i];
				if (map.containsKey(u[i])) {
					Obj o1 = o;
					Obj o2 = map.get(u[i]);
					if (o1.set.size() > o2.set.size()) {
						o1 = o2;
						o2 = o;
						map.put(u[i], o);
					}
					for (int e : o1.set) {
						Query qr = arr[e];
						qr.ans += o1.cost - qr.oc;
						qr.oc = o2.cost;
						qr.o = o2;
					}
					o2.set.addAll(o1.set);
				} else {
					map.put(u[i], o);
				}
			}
			tm.clear();

			while (!que1.isEmpty()) {
				Query qr = que1.peek();
				if (qr.sx > i) {
					break;
				}
				que1.poll();
				if (map.containsKey(qr.sy)) {
					Obj o = map.get(qr.sy);
					qr.oc = o.cost;
					qr.o = o;
					o.set.add(qr.i);
				} else {
					Obj o = new Obj();
					o.y = qr.sy;
					qr.oc = o.cost;
					qr.o = o;
					o.set.add(qr.i);
					map.put(qr.sy, o);
				}
				que2.add(qr);
			}

			while (!que2.isEmpty()) {
				Query qr = que2.peek();
				if (qr.tx > i) {
					break;
				}
				que2.poll();
				qr.ans += qr.o.cost - qr.oc;
				qr.ans += Math.abs(qr.ty - qr.o.y);
				qr.o.set.remove(qr.i);
			}
		}

		PrintWriter pw = new PrintWriter(System.out);
		for (Query qr : arr) {
			pw.println(qr.ans);
		}
		pw.flush();
	}

	static class Query {
		int i, sx, sy, tx, ty;
		long oc;
		long ans;
		Obj o;
	}

	static class Obj {
		int y;
		long cost;
		Set<Integer> set = new HashSet<>();
	}
