import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		long T = sc.nextLong();

		String direction = sc.next();

		List<Long> x1 = new ArrayList<>(); //forward facing
		List<Long> x2 = new ArrayList<>(); //backward facing


		for(int i = 0; i < N; i++) {
			long x = sc.nextLong();

			if(direction.charAt(i) == '1') {
				x1.add(x);
			}else {
				x2.add(x);
			}
		}

		Collections.sort(x1);
		Collections.sort(x2);

		int l = 0, r = 0;
		long ans = 0;

		for(int i = 0; i < x1.size(); i++) {
			while(l < x2.size() && x2.get(l) < x1.get(i)) l++;
			while(r < x2.size() && x2.get(r) <= x1.get(i) + 2 * T) r++;
			ans += r - l;
		}

		System.out.println(ans);
		sc.close();
	}
}

