			dp1[i] = Integer.MAX_VALUE;
		}

		for (int i = 0; i < n; i++) {
			int idx = 0;

			idx = Arrays.binarySearch(dp0, a[i]);
			if (idx < 0) idx = ~idx;
			dp0[idx] = a[i];

			idx = Arrays.binarySearch(dp1, a[i]);
