import java.util.Scanner;



public class Main {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();

        int[] x = new int[n];

        for (int i = 0; i < n; i++) {

            x[i] = scanner.nextInt();

        }

        scanner.close();



        int[] result = solve(n, x);



        for (int i = 0; i < n; i++) {

            System.out.print(result[i] + " ");

        }

    }



    public static int[] solve(int n, int[] x) {

        int[] sum = new int[n + 2];

        int[] f = new int[n + 1];

        int[] result = new int[n];



        for (int i = 0; i < n; i++) {

            sum[x[i] + 1]++;

            sum[i + 2]--;

        }



        for (int i = 1; i <= n; i++) {

            sum[i] += sum[i - 1];

            f[i] = Math.max(f[i - 1], sum[i]);

        }



        for (int i = 0; i < n; i++) {

            result[i] = Math.max(0, i + 1 - f[n - i]);

        }



        return result;

    }

}

