import java.util.ArrayDeque;

import java.util.Deque;

import java.util.Scanner;



public class Main {

	public static void main(String[] args) {

		try(Scanner sc = new Scanner(System.in);) {

			int n = sc.nextInt();

			long[] h = new long[n];

			for(int i = 0; i < n; i++) h[i] = sc.nextLong();

			Deque<Pair> deq = new ArrayDeque<Pair>();

			long ans = 1;

			StringBuilder sb = new StringBuilder(); 

			for(int i = 0; i < n; i++) {

				int cnt = 1;

				while(!deq.isEmpty() && deq.peekLast().h <= h[i]) {

					Pair p = deq.pollLast();

					ans -= p.h * p.c;

					cnt += p.c;

				}

				ans += h[i] * cnt;

				deq.add(new Pair(h[i], cnt));

				sb.append(ans).append(" ");



			}



			System.out.println(sb.toString());

		}

	}

}



class Pair {

	long h;

	long c;



	public Pair(long h, long c) {

		this.h = h;

		this.c = c;

	}

}

