	public static boolean isPalindrome(String s) {

		List<Character> c = new ArrayList<>();

		for (int i = 0; i < s.length(); i++) {

			c.add(s.charAt(i));

		}



		Collections.reverse(c);



		String rs = new String();

		for (int i = 0; i < c.size(); i++) {

			rs += c.get(i);

		}



