        for (int i = 0; i < K; i++) dp[(1 << i)][i] = 0;
        for (int mask = 0; mask < (1 << K); mask++) {
            PriorityQueue<long[]> path = new PriorityQueue<>(Comparator.comparing(a -> a[0]));
            for (int u = 0; u < N; u++) {
