  i = 1
  while count < n:
    n-=count
    if not i%2:
      count *= 10
    i+=1
  n = str(n-1+10**((i-1)//2))
  m = ""
  for nn in n:
    m = nn + m
  if i%2:
    print(n[:-1] + m)
  else:
    print(n+m)
