#!/usr/bin/env python3
import sys
from collections import deque
import heapq

def main():
    H, W, Y = map(int, input().split())

    A = [list(map(int, input().split())) for _ in range(H)]

    pos = []
    ok = [False]*(W*H)
    heapq.heapify(pos)
    for i in range(H):
        for j in range(W):
            if i == 0 or i == H-1 or j == W-1 or j == 0:
                heapq.heappush(pos, (A[i][j], i*W+j))
                ok[i*W+j] = True

    arrive = [False]*(W*H)

    def solve(sx, sy, tmp):
        ret = 0
        if arrive[sx*W+sy]:
            return ret
        q = deque([(sx*W+sy)])
        arrive[sx*W+sy] = True
        ret += 1
        while q:
            xy = q.popleft()
            x, y = xy//W, xy%W
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x+dx, y+dy
                nxy = nx*W+ny
                if 0 <= nx < H and 0 <= ny < W and not arrive[nxy]:
                    if A[nx][ny] <= tmp:
                        arrive[nxy] = True
                        ret += 1
                        q.append(nxy)
                    else:
