import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		try(Scanner sc = new Scanner(System.in);) {
			long n = sc.nextLong();
			List<Pair> ps = new ArrayList<Pair>();
			for(long i = 2; i * i <= n; i++) {
				if(n % i != 0) continue;
				StringBuilder sb = new StringBuilder();
				String s = sb.append(i).reverse().toString();
				long j = Long.valueOf(s);
				if(s.contains("0")) continue;
				if(n % j != 0) continue;
				if(i <= j) ps.add(new Pair(i, j));
			}

			Rec rec = (r, m) -> {
				if(isPalindrome(String.valueOf(m))) return String.valueOf(m);

				for(Pair p : ps) {
					long xy = p.x * p.y;
					if(m % xy != 0) continue;
					String s = r.f(r, m / xy);
					if(s.equals("-1")) continue;
					return String.valueOf(p.x) + "*"+ s + "*" + String.valueOf(p.y);
				}

				return "-1";
			};

			System.out.println(rec.f(rec, n));
		}
	}

	interface Rec{
		String f(Rec r, long n);
	}

	static boolean isPalindrome(String s) {
		if(s.contains("0")) return false;
		String rs = new StringBuilder().append(s).reverse().toString();
		return s.equals(rs);
	}
}

class Pair {
	long x;
	long y;

	public Pair(long x, long y) {
		this.x = x;
		this.y = y;
	}
}

