import java.io.*;
import java.util.*;

class ACAuto {
    static int DIM = 26;
    ACAuto[] child = new ACAuto[DIM];
    ACAuto fail;
    int ends;
    int matchTimes = 0;

    // returns end node
    public ACAuto add(String p) {
        int n = p.length();
        ACAuto root = this;
        for (int i = 0; i < n; i++) {
            int c = p.charAt(i) - 'a';
            if (root.child[c] == null) {
                root.child[c] = new ACAuto();
            }
            root=root.child[c];
        }
        root.ends += 1;
        return root;
    }

    // create virtual links and cal match times
    public void match(String s) {
        ACAuto root = this;
        List<ACAuto> nodes = new ArrayList<>();
        Deque<ACAuto> deque = new ArrayDeque<>((int) 1e5 + 1);
        root.fail = new ACAuto();
        Arrays.fill(root.fail.child, root);
        deque.add(root);
        while (!deque.isEmpty()) {
            ACAuto cur = deque.pollFirst();
            nodes.add(cur);
            for (int i = 0; i < DIM; i++) {
                if (cur.child[i] == null) {
                    cur.child[i] = cur.fail.child[i];
                } else {
                    cur.child[i].fail = cur.fail.child[i];
                    deque.add(cur.child[i]);
                }
            }
        }

        ACAuto cur = this;
        for (int i = 0; i < s.length(); i++) {
            cur = cur.child[s.charAt(i) - 'a'];
            cur.matchTimes += 1;
        }
        for (int i = nodes.size() - 1; i >= 0; i--) {
            ACAuto node = nodes.get(i);
            node.fail.matchTimes += node.matchTimes;
        }
    }

}

public class Main implements Runnable {
    public void solve() {
        String s = next();
        int q = nextInt();
        ACAuto root = new ACAuto();
        List<ACAuto> ends = new ArrayList<>();
        for (int i = 0; i < q; i++) {
            String t = next();
            ends.add(root.add(t));
        }
        root.match(s);
        for (ACAuto end : ends) {
            out.println(end.matchTimes);
        }
    }

    public static void main(String[] args) throws Exception {
        new Thread(null, new Main(), "CustomThread", 1024 * 1024 * 100).start();
    }

    @Override
    public void run() {
        int t = 1;
        for (int i = 0; i < t; i++) {
            new Main().solve();
        }
        out.flush();
    }

    static PrintWriter out = new PrintWriter(System.out, false);
    static InputReader in = new InputReader(System.in);
    static String next() { return in.next(); }
    static int nextInt() { return Integer.parseInt(in.next()); }
    static long nextLong() { return Long.parseLong(in.next()); }
    static class InputReader {
        public BufferedReader reader;
