import java.io.*;
import java.util.*;

class TreeCenter {
    List<List<Integer>> g;
    int[] cnt;

    public int center (List<List<Integer>> g, int start, int nVertex) {
        this.g = g;
        cnt = new int[g.size()];
        return dfs(start, -1, nVertex);
    }

    private int dfs(int i, int p, int n) {
        cnt[i]=1;
        int max = 0;
        int sum = 1;
        for (Integer ch : g.get(i)) {
            if (ch == p) continue;
            int r = dfs(ch, i, n);
            if (r != -1) return r;
            cnt[i] += cnt[ch];
            sum += cnt[ch];
            max = Math.max(max, cnt[ch]);
        }
        max = Math.max(max, n - sum);
        if (max * 2 <= n) {
            return i;
        }
        return -1;
    }

}

