#!/usr/bin/env python3
# Nyaanさんの提出 https://atcoder.jp/contests/abc351/submissions/52777033 のpython翻訳

import sys
sys.setrecursionlimit(10**6)

import pypyjit
pypyjit.set_param('max_unroll_recursion=-1')

class StaticTopTree:
    def __init__(self, g, root=0):
        self.g = g
        self.root = root
        self.n = len(g)
        self.P = [-1] * (4 * self.n)
        self.L = [-1] * (4 * self.n)
        self.R = [-1] * (4 * self.n)
        self.T = ['Vertex'] * (4 * self.n)
        self.add_buf = self.n
        self.stt_root = self.build()

    def dfs(self, c):
        s, best = 1, 0
        for i in range(len(self.g[c])):
            t = self.dfs(self.g[c][i])
            s += t
            if best < t:
                best = t
                self.g[c][i], self.g[c][0] = self.g[c][0], self.g[c][i]
        return s

    def add(self, k, l, r, t):
        if k == -1:
            k = self.add_buf
            self.add_buf += 1
        self.P[k], self.L[k], self.R[k], self.T[k] = -1, l, r, t
        if l != -1:
            self.P[l] = k
        if r != -1:
            self.P[r] = k
        return k

    def merge(self, a, t):
        if len(a) == 1:
            return a[0]
        u = sum(size for _, size in a)
        b, c = [], []
        for i, s in a:
            (b if u > s else c).append((i, s))
            u -= 2 * s
        i, si = self.merge(b, t)
        j, sj = self.merge(c, t)
        return self.add(-1, i, j, t), si + sj

    def compress(self, i):
        chs = [self.add_vertex(i)]
        while self.g[i]:
            chs.append(self.add_vertex(i := self.g[i][0]))
        return self.merge(chs, 'Compress')

    def rake(self, i):
        chs = [self.add_edge(self.g[i][j]) for j in range(1, len(self.g[i]))]
        return self.merge(chs, 'Rake') if chs else (-1, 0)

    def add_edge(self, i):
        j, sj = self.compress(i)
        return self.add(-1, j, -1, 'AddEdge'), sj

    def add_vertex(self, i):
        j, sj = self.rake(i)
        return self.add(i, j, -1, 'Vertex' if j == -1 else 'AddVertex'), sj + 1

    def build(self):
        self.dfs(self.root)
        i, _ = self.compress(self.root)
        return i

