import java.util.*;





public class Main {



    public static void main(String[] args) {

        try (Scanner scanner = new Scanner(System.in)) {



            int n = scanner.nextInt();

            int m = scanner.nextInt();



            Node[] nodes = new Node[n];

            for (int i=0;i<n;i++)

                nodes[i]=new Node(i);

            for (int i=0;i<m;i++) {

                int a = scanner.nextInt()-1;

                int b = scanner.nextInt()-1;

                nodes[a].friends.add(nodes[b]);

                nodes[b].friends.add(nodes[a]);

            }



            long result = 0;



            boolean[] marked = new boolean[n];

            for (int i=0;i<n;i++) {

                int groupSize = 0;

                // rcは二重に数えられる←重要

                int relationCount = 0;

                Deque<Node> deque = new LinkedList<>();

                deque.addLast(nodes[i]);

                while (!deque.isEmpty()) {

                    Node node = deque.pollFirst();

                    if (marked[node.id]) continue;

                    marked[node.id]=true;

                    groupSize++;

                    relationCount+=node.friends.size();

                    deque.addAll(node.friends);

                }

                // 制約上rc<int_max

                relationCount>>=1;

                result+=(long)groupSize*(groupSize-1)/2-relationCount;

            }



            System.out.println(result);



        }

    }



}



class Node {



    int id;

    Set<Node> friends;



    public Node(int id) {

        this.id=id;

        friends = new HashSet<>();

    }

}

