        // 自分の得意な言語で

        // Let's チャレンジ！！

        Scanner sc = new Scanner(System.in);

        Integer a = sc.nextInt();

        Integer turn = sc.nextInt();

        //縦＝c%aが同値　横＝c/aが同値　斜めc%aとc/aの解に差が出ないのとc%a+c/a=a+1

        /*

        横は123

        縦 012

        0  345

        1  678

        2



        */

        int[] tate=new int[a];

        int[] yoko=new int[a];

        int nana=0;//右上

        int nan1=0;//←上

        int r=0;

        //int[][] card = new int[a][a];

        //int[] kari = new int[a*a];

        for(int g=0; g<turn; g++){

          Integer c = sc.nextInt();

          c-=1;//5なら

          tate[c%a]++;//1

          //System.out.println(tate[c%a]+"tate");

          if(tate[c%a]==a){

            System.out.println(g+1);

            r++;

            break;

          }

          yoko[c/a]++;//1

          //System.out.println(yoko[c/a]+"yoko");

          if(yoko[c/a]==a){

            System.out.println(g+1);

            r++;

            break;

          }

          if((c%a+c/a)+2==a+1){//(4%3+4/3)+2==4

            nana++;

            //System.out.println(nana+"nana");

            if(nana==a){

              System.out.println(g+1);

              r++;

              break;

            }

          }

          if(c%a==c/a){//4%3=4/3

            nan1++;

            //System.out.println(nan1+"nan1");

            if(nan1==a){

              System.out.println(g+1);

              r++;

              break;

            }

          }

          //System.out.println(c%a+" "+c/a);

        }



        if(r==0){

          System.out.println(-1);

        }





    }

}

