        int[][] cards = new int[N][3];

        for (int i = 0; i < N; i++) {

            cards[i][0] = reader.nextInt();

            cards[i][1] = reader.nextInt();

            cards[i][2] = i;

        }

        Arrays.sort(cards, Comparator.comparingInt(a -> a[1]));

