import java.util.*;

import java.io.*;

public class Main{



    static class Pair implements Comparable<Pair>{

        String str;

        int rating;



        public Pair(String str, int rating){

            this.str = str;

            this.rating = rating;

        }



        public int compareTo(Pair that){

            return this.str.compareTo(that.str);

        }

    }



    public static void main(String[] args) throws Exception{

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int n = Integer.parseInt(br.readLine());

        int terms = n;

        List<Pair> list = new ArrayList<>();

        int totalRating = 0;

        while(terms-->0){

            String[] input = br.readLine().split(" ");

            int rating = Integer.parseInt(input[1]);

            totalRating += rating;

            Pair pair = new Pair(input[0], rating);

            list.add(pair);

        }

        Collections.sort(list);

        System.out.println(list.get(totalRating%n).str);

    }



    private static int calc(int tH){

        long st = 1l;

        int day = 1;

        long mult = 2;

        while(st <= (long)tH){

            day++;

            st += mult;

            mult *= 2;

        }

        return day;

    }

}

