a = [0] * n

b = [0] * n

for i in range(n):

    a[i], b[i] = map(int, input().split())



# dp[取り除いたカードの集合] = True のとき高橋が勝つ

dp = [False] * (1 << n)

dp[0] = False  # すべてのカードが取り除かれた状態では青木君が勝つ



for i in range(1 << n):

    if dp[i] is False:

        for j in range(n):

            for k in range(j + 1, n):

                if (a[j] == a[k] or b[j] == b[k]) and (i & (1 << j)) == 0 and (i & (1 << k)) == 0:

                    new_state = i ^ (1 << j) ^ (1 << k)

                    dp[new_state] = True



print("Takahashi" if dp[(1 << n) - 1] else "Aoki")

