import java.io.*;

import java.util.StringTokenizer;



public class Main {

    private static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

    private static BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));

    private static StringTokenizer st;



    public static void main(String[] args) throws IOException {

        st = new StringTokenizer(reader.readLine());

        long K = Long.parseLong(st.nextToken());

        st = new StringTokenizer(reader.readLine());

        long Sx = Long.parseLong(st.nextToken());

        long Sy = Long.parseLong(st.nextToken());

        st = new StringTokenizer(reader.readLine());

        long Tx = Long.parseLong(st.nextToken());

        long Ty = Long.parseLong(st.nextToken());

        if (K == 1) {

            writer.write(Long.toString(Math.abs(Sx - Tx) + Math.abs(Sy - Ty)));

            writer.newLine();

            writer.flush();

            return;

        }

        long best = Long.MAX_VALUE;

        boolean sInBig = (Sx / K + Sy / K) % 2 == 1;

        boolean tInBig = (Tx / K + Ty / K) % 2 == 1;

        if (Sx / K == Tx / K && Sy / K == Ty / K) {

            if ((Sx / K + Sy / K) % 2 == 0) {

                best = Math.abs(Sx - Tx) + Math.abs(Sy - Ty);

            } else {

                best = 0;

            }

        }

        if (sInBig && tInBig) {

            best = Math.min(best, distBetweenBigs(Sx / K, Sy / K, Tx / K, Ty / K, K));

        } else if (sInBig) {

            long[] dists = distToBigNeighbours(Tx, Ty, K);

            long[][] neight = bigNeighbours(Tx, Ty, K);

            for (int i = 0; i < 4; i++) {

                best = Math.min(best, dists[i] + distBetweenBigs(Sx / K, Sy / K, neight[i][0], neight[i][1], K));

            }

        } else if (tInBig) {

            long[] dists = distToBigNeighbours(Sx, Sy, K);

            long[][] neight = bigNeighbours(Sx, Sy, K);

            for (int i = 0; i < 4; i++) {

                best = Math.min(best, dists[i] + distBetweenBigs(Tx / K, Ty / K, neight[i][0], neight[i][1], K));

            }

        } else {

            long[] distsS = distToBigNeighbours(Sx, Sy, K);

            long[][] neightS = bigNeighbours(Sx, Sy, K);

            long[] distsT = distToBigNeighbours(Tx, Ty, K);

            long[][] neightT = bigNeighbours(Tx, Ty, K);

            for (int i = 0; i < 4; i++) {

                for (int j = 0; j < 4; j++) {

                    best = Math.min(best, distsS[i] + distsT[j] + distBetweenBigs(neightS[i][0], neightS[i][1], neightT[j][0], neightT[j][1], K));

                }

            }

        }

        writer.write(Long.toString(best));

        writer.newLine();

        writer.flush();

    }



    static long[] distToBigNeighbours(long Sx, long Sy, long K) {

        Sx %= K;

        Sy %= K;

        long[] dist = {Sx + 1, Sy + 1, K - Sx, K - Sy};

        boolean change = true;

        while (change) {

            change = false;

            for (int i = 0; i < 4; i++) {

                long original = dist[i];

                dist[i] = Math.min(dist[i], dist[(i + 1) % 4] + 2);

                dist[i] = Math.min(dist[i], dist[(i + 3) % 4] + 2);

                dist[i] = Math.min(dist[i], dist[(i + 2) % 4] + 4);

                if (dist[i] != original) {

                    change = true;

                }

            }

        }

        return dist;

    }



    static long[][] bigNeighbours(long x, long y, long K) {

        x /= K;

        y /= K;

        return new long[][]{{x - 1, y}, {x, y - 1}, {x + 1, y}, {x, y + 1}};

    }



    static long distBetweenBigs(long x1, long y1, long x2, long y2, long K) {

        long diagonal = Math.min(Math.abs(x1 - x2), Math.abs(y1 - y2));

        long remainder = Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2)) - diagonal;

        return  2 * diagonal + Math.min(2 * remainder, (K + 1) * remainder / 2);

    }

}

