        sc=new Scanner(System.in);

        out=new PrintWriter(System.out);

        new Main().solve();

        out.flush();

    }



    public void solve(){

        String s=sc.next();

        String t=sc.next();

        int last=0;

        loop:for(int i=0;i<s.length();i++){

            for(int j=last;j<t.length();j++){

                if(s.charAt(i)==t.charAt(j)){

                    out.print((j+1)+" ");

                    last=j+1;

                    continue loop;

                }

            }

        }

        out.println();

    }

}

