public class Main {

    private static long[] s;



    private static long getsum(int l, int r) {

        return s[r] - s[l - 1];

    }



    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);

        int n = in.nextInt();

        int q = in.nextInt();

        int[] last = new int[n + 1];

        long[] a = new long[n + 1];

        s = new long[q + 1];

        int now = 0;

        for (int i = 1; i <= q; i++) {

