            if (last[x] > 0) {

                a[x] += getsum(last[x], i - 1);

                last[x] = 0;

                now--;

            } else {

                last[x] = i;

                now++;

            }

            s[i] = s[i - 1] + now;

        }

        for (int i = 1; i <= n; i++)

            if (last[i] > 0)

                a[i] += getsum(last[i], q);

        for (int i = 1; i <= n; i++)

            System.out.printf("%d ", a[i]);

        in.close();

    }

