      depth = new long[n+1];

      parent = new int[n+1];



      depth[1] = 1L;



      dfs1(1,-1);



      long sumd = 0L;

      for(int k = 1; k <= n; k++){

         sumd += depth[k];

      }



      if(m < n || m > sumd){

         out.println("No");

         out.close();

         return;

      }



      tot = (long)n;

      val = new int[n+1];

      val[1] = 1;



      dfs2(1,-1);



      l = 1;

      r = n;

      answer = new int[n+1];

      dfs3(1,-1);



      StringJoiner sj = new StringJoiner(" ");

      for(int k = 1; k <= n; k++){

         sj.add("" + answer[k]);

      }

      out.println("Yes");

      out.println(sj.toString());









      out.close();

   }



   public static void dfs3(int v, int p){

      for(int nei : adj.get(v)){

         if(nei == p) continue;

         dfs3(nei,v);

      }



      if(v == 1 || val[v] == val[p]){

         answer[v] = l;

         l++;

      } else { 

         answer[v] = r;

         r--;

      }



   }



   public static void dfs2(int v, int p){

      if(v != 1){

         if(tot + subsize[v] <= m){

            tot += subsize[v];

            val[v] = val[p] + 1;

         } else {

            val[v] = val[p];

         }

      }



      for(int nei : adj.get(v)){

         if(nei == p) continue;

         dfs2(nei,v);

      }

   }



   public static void dfs1(int v, int p){

