public class Main {

    public static class Node {
        int id;
        long mx, seMx;

        public Node() {
            id = 0;
            mx = Long.MIN_VALUE;
            seMx = Long.MIN_VALUE;
        }

        public Node(int id, long mx, long seMx) {
            this.id = id;
            this.mx = mx;
            this.seMx = seMx;
        }

        public long query(int id) {
            if (this.id == id) return seMx;
            return mx;
        }

        public void update(long x, int id) {
            if (this.id == id) mx = Math.max(mx, x);
            else {
                if (x > mx) {
                    this.id = id;
                    seMx = mx;
                    mx = x;
                }else if (x > seMx) {
                    seMx = x;
                }
            }
        }

    }

    public static void solve() throws IOException{
        int n = in.nextInt();
        int k = in.nextInt();
        int[] c = new int[n+1];
        int[] v = new int[n+1];
        for (int i = 1; i <= n; i++) {
            c[i] = in.nextInt();
            v[i] = in.nextInt();
        }

        Node[] dp = new Node[k+1];
        for (int i = 0; i <= k; i++) dp[i] = new Node();
        long[] f = new long[k+1];
        Arrays.fill(f, Long.MIN_VALUE);
        dp[0] = new Node(0, 0, Long.MIN_VALUE);
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                f[j] = dp[j].query(c[i]) + v[i];
            }
            for (int j = k; j > 0; j--) dp[j] = dp[j-1];
            dp[0] = new Node();
            for (int j = 0; j <= k; j++) {
                dp[j].update(f[j], c[i]);
            }
        }
        if (dp[k].mx < 0) out.println(-1);
        else out.println(dp[k].mx);
    }

