class Solution:
    def neq_number(self):
        def f(x):
            d = []
            while x:
                d.append(int(x%10))
                x = x//10
            d.reverse()

            # print("DDDD", d)
            m = len(d)
            # print("MMMM", m)
            p9 = [1 for _ in range(m+1)]

            for i in range(m):
                p9[i+1] = p9[i]*9
            # print(p9)
            cnt = 0
            for i in range(m-1):
                cnt += p9[i+1]

            prev_digit = 0
            for i in range(m):
                di = d[i]

                l = 1 if i==0 else 0
                r = di+1 if (i == m-1) else di
                r = int(r)
                for j in range(l, r):
                    if j == prev_digit:
                        continue
                    cnt += p9[m-1-i]
                if prev_digit == di:
                    break
                prev_digit = di

            return int(cnt)



        def solve():
            k = int(input())
            lo, hi = 0, 2e18

            while lo+1 < hi:
                mid = (lo+hi)//2
                cnt = int(f(mid))
                if cnt>= k:
                    hi = mid
                else:
                    lo = mid

            return int(hi)

        T = int(input())
        while T:
            T-=1
            print(solve())

        return 0



