def solve(n,a):
    def migi_is_big(i):
        if i+1 < n:
            return int(a[i+1]>a[i])
        else:
            return int(a[i-1]<a[i])

    def valid(i,p,flag):
        return int(p-i>0) ^ flag ^ int(a[p]>a[i]) ^ ((p-i)%2) ^ 1


    def check(i,k,flag):
        for j in range(k-2,k):
            if i+j < n and not valid(i,i+j,flag):
                return 0
            if 0 <= i-j and not valid(i,i-j,flag):
                return 0
        return 1


    ans = [-2]*n
    for k in range(3,n+3,2):
        if k > n:
            ans[0] = -1
            break
        if (a[k-2]>a[0]) == (a[k-1]>a[0]):
            ans[0] = k
            break
    for k in range(3,n+3,2):
        if k > n:
            ans[-1] = -1
            break
        if (a[n-1-(k-2)]>a[n-1]) == (a[n-1-(k-1)]>a[n-1]):
            ans[-1] = k
            break


    for i in range(n):
        if ans[i] != -2: continue

        flag = migi_is_big(i)
        for k in range(3,n+3,2):
            if not check(i,k,flag):
                break

        if k > n:
            ans[i] = -1
        else:
            ans[i] = k

        #print(i,k)
        for j in range(i+1,i+k-3):
            if j >= n-1: break
            ans[j] = 3

    return ans        

def brute(n,a):
    ans = [100]*n
    for i in range(n):
        for j in range(i+1,n+1,2):
            r = sorted(a[i:j])
            v = r[(j-i)//2]
            for k in range(i,j):
                if a[k] != v:
                    ans[k] = min(ans[k],j-i)

    for i in range(n):
        if ans[i] == 100: ans[i] = -1
    return ans

