public class Main {
	public static void main(String[] args) {
		try(Scanner sc = new Scanner(System.in);) {
			int n = Integer.parseInt(sc.next());
			long[][] p = new long[n][n];
			long[][] r = new long[n][n - 1];
			long[][] d = new long[n - 1][n];

			for(int i = 0; i < n; i++) 
				for(int j = 0; j < n; j++) 
					p[i][j] = Long.parseLong(sc.next());

			for(int i = 0; i < n; i++) 
				for(int j = 0; j < n - 1; j++) 
					r[i][j] = Long.parseLong(sc.next());

			for(int i = 0; i < n - 1; i++) 
				for(int j = 0; j < n; j++) 
					d[i][j] = Long.parseLong(sc.next());

			Pair[][] dp = new Pair[n][n];
			final long INF = 1L << 60;
			for(int i = 0; i < n; i++)
				for(int j = 0; j < n; j++) 
					dp[i][j] = new Pair(INF, 0);

			dp[0][0] = new Pair(0, 0);

			for(int i = 0; i < n; i++) {
				for(int j = 0; j < n; j++) {
					long[][] dist = new long[i + 1][j + 1];
					for(int  k = 0; k < i + 1; k++) Arrays.fill(dist[k], INF);
					dist[i][j] = 0;
					for(int y = i; y >= 0; y--) {
						for(int x = j; x >= 0; x--) {
							if(y < i) dist[y][x] = Math.min(dist[y][x], d[y][x] + dist[y + 1][x]);
							if(x < j) dist[y][x] = Math.min(dist[y][x], r[y][x] + dist[y][x + 1]);

							long c = Math.max(0, dist[y][x] - dp[y][x].m + p[y][x] - 1) / p[y][x];
							long t = dp[y][x].t + c + i - y + j - x;
							long m = dp[y][x].m + c * p[y][x] - dist[y][x];

							if(t < dp[i][j].t || t == dp[i][j].t && m > dp[i][j].m) dp[i][j] = new Pair(t, m);
						}
					}

				}
			}

			System.out.println(dp[n - 1][n - 1].t);
		}
	}
}

class Pair{
	long t;
	long m;

	public Pair(long t, long m) {
		this.t = t;
		this.m = m;
	}
}

