class Codechef {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();  // Number of test cases

        final long MOD = 1000000007L;  // Modulo value

        for (int i = 0; i < T; i++) {
            int N = sc.nextInt();  // Read N for each test case
            HashMap<Integer, Long> factorial = new HashMap<>();  // Use 'Long' to avoid overflow

            // Calculating factorials and storing them in a HashMap with modulo
            factorial.put(0, 1L);  // 0! is 1
            long fact = 1L;
            for (int j = 1; j <= N; j++) {
                fact = (fact * j) % MOD;
                factorial.put(j, fact);
            }

            // Computing the psum as required in the logic
            for (int j = 1; j <= N; j++) {
                int d = N - (j - 1);
                int L = d / j;
                long psum = 0;  // Using 'long' to store psum

                if (j == N) {  // Special case when j == N
                    psum = factorial.get(j) % MOD;
                } else if (d % j == 0) {
                    psum = (factorial.get(L) * factorial.get(N - L)) % MOD;
                } else {
                    int H = d % j;
                    int M = j - H;
                    psum = (factorial.get(L) * factorial.get(N - L - 1) % MOD * (L + 1) % MOD * (j - N % j) % MOD) % MOD;
                }

                System.out.print(psum + " ");
            }

            System.out.println();
        }

        sc.close();  // Close the scanner outside the loop to avoid resource leak
    }
}

