import java.util.Scanner;

class Main {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner sc = new Scanner(System.in);

        int t = sc.nextInt();

        while (t-- > 0) {
            int n = sc.nextInt();
            int[] b = new int[n + 1];

            for (int i = 1; i <= n; i++) {
                b[i] = sc.nextInt();
            }

            int count1 = countOccurrences(b, 1, 1, n - 1);
            int count2 = countOccurrences(b, 0, 2, n);

            int c12 = count1 + count2;
            int min = Math.min(c12, n - 1);
            int tc = n + min;
            System.out.println(tc);
        }

        sc.close();
    }

    private static int countOccurrences(int[] array, int target, int start, int end) {
        int count = 0;
        for (int i = start; i <= end; i++) {
            if (array[i] == target) {
                count++;
