import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner sc = new Scanner(System.in);
        int test = sc.nextInt();
        while (test-- > 0) {
            int n = sc.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = sc.nextInt();
            }

            // Initialize prefix and suffix sums
            long[] prefix = new long[n];
            long[] suffix = new long[n];

            // Compute prefix sum
            prefix[0] = arr[0];
            for (int i = 1; i < n; i++) {
                prefix[i] = prefix[i - 1] + arr[i];
            }

            // Compute suffix sum
            suffix[n - 1] = arr[n - 1];
            for (int i = n - 2; i >= 0; i--) {
                suffix[i] = suffix[i + 1] + arr[i];
            }

            // Set to store positions of zeros (empty grounds)
            HashSet<Integer> set = new HashSet<>();
            for (int i = 0; i < n; i++) {
                if (arr[i] == 0) {
                    set.add(i);
                }
            }

            // Calculate the number of ways
            int ways = 0;
            for (Integer i : set) {
                // Calculate the difference between prefix and suffix sums
                long leftSum = (i > 0 ? prefix[i - 1] : 0);
                long rightSum = (i < n - 1 ? suffix[i + 1] : 0);
                long diff = Math.abs(leftSum - rightSum);

                if (diff == 0) {
                    ways += 2; // Both directions
                } else if (diff == 1) {
                    ways += 1; // One direction
                }
            }
            System.out.println(ways);
        }
    }
}

