import sys
import bisect

def compute_prefix_sums(positions):
    prefix = [0]
    for pos in positions:
        prefix.append(prefix[-1] + pos)
    return prefix

def compute_sum(j, positions, prefix):
    L = len(positions)
    p = bisect.bisect_right(positions, j)
    if p == 0:
        return prefix[L] - L * j
    elif p == L:
        return p * j - prefix[p]
    else:
        return p * j - prefix[p] + prefix[L] - prefix[p] - (L - p) * j

def main():
    import sys
    import threading

    def run():
        T = int(sys.stdin.readline())
        for _ in range(T):
            line = ''
            while line.strip() == '':
                line = sys.stdin.readline()
            N_M = line.strip().split()
            N = int(N_M[0])
            M = int(N_M[1])
            A = []
            while len(A) < M:
                A += list(map(int, sys.stdin.readline().strip().split()))
            A_pos = []
            K_pos = []
            for idx, val in enumerate(A):
                pos = idx + 1
                if val == 1 or val == 3:
                    A_pos.append(pos)
                if val == 2 or val == 3:
                    K_pos.append(pos)
            A_pos_sorted = sorted(A_pos)
            K_pos_sorted = sorted(K_pos)
            prefix_A = compute_prefix_sums(A_pos_sorted)
            prefix_K = compute_prefix_sums(K_pos_sorted)
            B = []
            for j in range(1, M + 1):
                sum_A = compute_sum(j, A_pos_sorted, prefix_A)
                sum_K = compute_sum(j, K_pos_sorted, prefix_K)
                B.append(str(abs(sum_A - sum_K)))
            print(' '.join(B))
    threading.Thread(target=run,).start()

