import java.util.*;

class MinimumTotal
{
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt(); // Number of test cases

        while (t-- > 0) {
            int n = sc.nextInt(); // Number of ingredients
            long c = sc.nextLong(); // Cost per ingredient
            long s = sc.nextLong(); // Swap cost
            int m = sc.nextInt(); // Maximum weight Chef's bag can carry
            int[] w = new int[n]; // Array to store weights of ingredients

            // Reading the weights of ingredients
            for (int i = 0; i < n; i++) {
                w[i] = sc.nextInt();
            }

            int now = 0; // Index to keep track of current ingredient
            int sum = 0; // Sum of weights of picked ingredients
            // Greedily pick ingredients until bag weight limit is reached
            while (now < n && sum + w[now] <= m) {
                sum += w[now++];
            }

            long ans = now * c; // Initial answer based on greedy approach

            if (now == 0) {
                System.out.println(0); // If no ingredients can be picked, answer is 0
                continue; // Move to next test case
            }

            PriorityQueue < Integer > rq = new PriorityQueue < > (Comparator.reverseOrder()); // Max heap for remaining ingredients after 'now'
            for (int i = now; i < n; i++) {
                rq.add(w[i]);
            }

            PriorityQueue < Pair < Integer, Integer >> lq = new PriorityQueue < > (Comparator.comparingInt(Pair::getFirst)); // Min heap for picked ingredients
            for (int i = 0; i < now; i++) {
                lq.add(new Pair < > (w[i], i));
            }

            int[] hold = new int[now]; // Array to hold the weights of picked ingredients
            long cost = 0; // Total swap cost

            // Perform swaps optimally
            while (now > 0 && !lq.isEmpty() && !rq.isEmpty()) {
                Pair < Integer, Integer > lMinPair = lq.poll(); // Get the minimum weight ingredient picked
                int lMin = lMinPair.getFirst();
                int lIndex = lMinPair.getSecond();
                if (lIndex >= now) continue; // Skip if the picked ingredient index is out of range
                int rMax = rq.poll(); // Get the maximum weight ingredient remaining
                if (lMin >= rMax) break; // If no more swaps can be done, break the loop
                if (hold[lIndex] > 0) {
                    rq.add(hold[lIndex]);
                    cost -= s; // Reduce the swap cost as ingredient is returned back
                }
                cost += s; // Add the swap cost
                sum += rMax - lMin; // Update the total weight by adding the difference in weights
                w[lIndex] = rMax; // Update the weight of picked ingredient
                hold[lIndex] = rMax; // Store the weight of picked ingredient
                lq.add(new Pair < > (rMax, lIndex)); // Add the new picked ingredient to heap
                while (sum > m) {
                    sum -= w[--now]; // Reduce the sum of weights until it's within bag weight limit
                    ans = Math.min(ans, now * c + cost); // Update the answer with minimum cost
                    rq.add(w[now]); // Add the removed ingredient back to remaining ingredients heap
                    if (hold[now] > 0) cost -= s; // Reduce the swap cost if the ingredient is returned back
                }
            }

            System.out.println(ans); // Print the minimum total number of coins needed
        }
    }

    static class Pair < U, V > {
        U first;
        V second;

        Pair(U first, V second) {
            this.first = first;
            this.second = second;
        }

        U getFirst() {
            return first;
        }

        V getSecond() {
            return second;
        }
    }
}

