import java.io.*;
import java.util.*;

public class Main implements Runnable {
    static final int MOD = 1_000_000_007;
    private static void solve(MyScanner in, PrintWriter out) {
        int n = in.nextInt();
        int r = in.nextInt();
        List<Integer>[] adj = new List[n + 1];
        for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            int u = in.nextInt();
            int v = in.nextInt();
            adj[u].add(v);
            adj[v].add(u);
        }
        List<Integer>[] divs = new List[n + 1];
        Deque<Integer>[] euler = new Deque[n + 1];
        Set<Integer>[] good = new Set[n + 1];
        for (int i = 1; i <= n; i++) {
            divs[i] = new ArrayList<>();
            euler[i] = new ArrayDeque<>();
            good[i] = new HashSet<>();
        }
        for (int i = 1; i <= n; i++) {
            for (int j = i; j <= n; j += i) divs[j].add(i);
        }
        dfs(adj, r, -1, divs, euler, good);
        outer:
        for (int i = 1; i <= n; i++) {
            for (int j = divs[i].size() - 1; j >= 0; j--) {
                int div = divs[i].get(j);
                if (good[i].contains(div)) {
                    out.print(div + " ");
                    continue outer;
                }
            }
            out.print(-1 + " ");
        }
        out.println();
    }

    private static void dfs(List<Integer>[] adj, int v, int parent, List<Integer>[] divs, Deque<Integer>[] euler, Set<Integer>[] good) {
        for (int i = 0; i < divs[v].size(); i++) {
            int div = divs[v].get(i);
            while (!euler[div].isEmpty() && euler[div].peek() > v) {
                good[euler[div].poll()].add(div);
            }
            euler[div].push(v);
        }
        for (int w : adj[v]) {
            if (w == parent) continue;
            dfs(adj, w, v, divs, euler, good);
        }
        for (int i = 0; i < divs[v].size(); i++) {
            int div = divs[v].get(i);
            if (!euler[div].isEmpty() && euler[div].peek() == v) euler[div].poll();
        }
    }

    public static void main(String[] args) {
        new Thread(null, new Main(), "Main", 1 << 28).start();
    }

    public void run() {
        MyScanner in = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int t = in.nextInt();
//        int t = 1;
        while (t-- > 0) solve(in, out);
        out.close();
    }

    //-----------MyScanner class for faster input----------
    public static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

