import java.io.*;
import java.util.*;
import java.lang.*;
import java.math.*;

class Codechef {
    private static FastScanner in = new FastScanner();
    private static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        int t = in.nextInt();
        while (t-- > 0){
            solve();
        }
    }

    static int MOD7 = (int)(1e9+7);

    private static void solve() { 
        int n = in.nextInt();
        int k = in.nextInt();

        PriorityQueue<Long> minHeap = new PriorityQueue<>();
        long mx=-1, num;
        for(int i=0; i<n; i++){
            num = in.nextLong();
            mx = Math.max(mx,num);
            minHeap.offer(num);   
        }

        while(k>0 && 2*minHeap.peek()<mx){
            minHeap.offer(2*minHeap.poll());
            k--;
        }

        long ans = 0;
        long pow = binpow(2, (long)(k/n), MOD7); // No need to recompute 2^(k/n) for every element

        while(!minHeap.isEmpty()){
            num = minHeap.poll();
            ans += pow * num;
            if(k % n != 0){
                 ans += num*pow;
                 k--;
            }
            ans %= MOD7;
        }

        out.println(ans);
        out.flush();
    }

    static long binpow(long a, long b, long mod){
        long res = 1;
        while (b>0) {
            if ((b & 1) != 0) {
                res = (res * a)%mod;
            }
            a = (a * a)%mod;
            b >>= 1;
        }
        return res;
    }

