		    int n = sc.nextInt();
		    int[] arr = new int[n];

		    for(int i=0; i<n; i++) arr[i] = sc.nextInt();

		    ArrayList<Integer> al = new ArrayList<>(); //prefix minimum array
		    al.add(arr[0]);

		    for(int i=1; i<n; i++){
		        if(al.get(al.size()-1)>=arr[i]) al.add(arr[i]);
		    }

		    int ans = n;

		    Collections.sort(al);

		    for(int i=0; i<al.size(); i++){
		        ans = Math.min(ans, n-i-1+al.get(i));
		    }

		    System.out.println(ans);
		}
	}
}

