    n = len(arr)
    beg = 0
    end = n - 1
    while beg <= end:
        mid = (beg + end) // 2
        if arr[mid] <= value:
            beg = mid + 1
        else:
            end = mid - 1
    pos = beg - 1
    return value * (pos + 1) - p[pos + 1] + p[n] - p[pos + 1] - value * (n - pos - 1)

