import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = (long) 1e9 + 7;
    static final int MAX_VAL = 2000;

    // Function to compute a^b mod MOD
    static long powerMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // Precompute factorials and inverse factorials
        long[] factorial = new long[MAX_VAL + 1];
        long[] inverseFactorial = new long[MAX_VAL + 1];
        factorial[0] = inverseFactorial[0] = 1;

        for (int i = 1; i <= MAX_VAL; i++) {
            factorial[i] = factorial[i - 1] * i % MOD;
        }
        inverseFactorial[MAX_VAL] = powerMod(factorial[MAX_VAL], MOD - 2, MOD);

        for (int i = MAX_VAL - 1; i >= 0; i--) {
            inverseFactorial[i] = inverseFactorial[i + 1] * (i + 1) % MOD;
        }

        // Precompute powers of inv2
        long inv2 = powerMod(2, MOD - 2, MOD);
        long[] inv2Powers = new long[MAX_VAL + 1];
        inv2Powers[0] = 1;

        for (int i = 1; i <= MAX_VAL; i++) {
            inv2Powers[i] = inv2Powers[i - 1] * inv2 % MOD;
        }

        int testCases = Integer.parseInt(br.readLine().trim());
        while (testCases-- > 0) {
            String[] nm = br.readLine().split(" ");
            int n = Math.min(Integer.parseInt(nm[0]), MAX_VAL);
            int m = Math.min(Integer.parseInt(nm[1]), MAX_VAL);

            long total = 0;
            List<Long> results = new ArrayList<>();

            for (int i = 1; i <= m; i++) {
                if (i >= n) {
                    long combination = factorial[i - 1] * inverseFactorial[n - 1] % MOD * inverseFactorial[i - n] % MOD;
                    combination = combination * inv2Powers[i] % MOD;
                    total = (total + combination) % MOD;
                }
                results.add(total);
            }

            for (int i = 0; i < results.size(); i++) {
                if (i > 0) out.print(' ');
                out.print(results.get(i));
            }
            out.println();
        }

        out.close();
    }
}

