def max_present_days(n, s):
    max_zeros_length = 0
    current_zeros_length = 0
    for i in range(n):
        if s[i] == '0':
            current_zeros_length += 1
            max_zeros_length = max(max_zeros_length, current_zeros_length)
        else:
            current_zeros_length = 0
    if max_zeros_length == 0:
        return n
    present_days = 0
    for i in range(n):
        if s[i] == '1':
            present_days += 1
    return present_days + max_zeros_length if present_days + max_zeros_length <= n else n

X = int(input())
while X > 0:
    n = int(input())
    s = input()
    print(max_present_days(n, s))
    X -= 1

import java.util.Scanner;

class Codechef {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt(); // Number of test cases

        while (t-- > 0) {
            int n = sc.nextInt(); // Length of the string
            String s = sc.next(); // Binary string

            int totalOnes = 0; // Count of total '1's in the string
            for (char c : s.toCharArray()) {
                if (c == '1') totalOnes++;
            }

            int maxAttendance = totalOnes; // Start with the current attendance
            int currentZeros = 0; // Count zeros in the current substring
            int maxZeros = 0; // Maximum length of contiguous zeros

            for (int i = 0; i < n; i++) {
                if (s.charAt(i) == '0') {
                    currentZeros++;
                    maxZeros = Math.max(maxZeros, currentZeros);
                } else {
                    currentZeros = 0; // Reset count on encountering '1'
                }
            }

            // Calculate maximum attendance after marking a substring of zeros as '1's
            if (maxZeros > 0) {
                maxAttendance = Math.max(maxAttendance, totalOnes + maxZeros);
            }

            System.out.println(maxAttendance);
        }

        sc.close();
    }
}

