        int n = scanner.nextInt();
        long[] arr = new long[n];
        SegmentTree st = new SegmentTree(n, Main::max_value, 0);

        for (int i = 0; i < n; ++i) {
            arr[i] = scanner.nextLong();
            st.update(i, arr[i]);
        }

        long[] previousGreaterEqual = new long[n];
        long[] nextGreaterEqual = new long[n];
        Arrays.fill(previousGreaterEqual, -1);
        Arrays.fill(nextGreaterEqual, n);
        Stack<Long> stack = new Stack<>();

        for (int i = 0; i < n; ++i) {
            while (!stack.isEmpty() && arr[stack.peek().intValue()] <= arr[i]) {
                stack.pop();
            }
            if (stack.size() == 1) {
                previousGreaterEqual[i] = stack.peek();
            } else if (stack.size() > 1) {
                System.out.println(0);
                return;
            }
            stack.push((long) i);
        }

        long minK = 0;
        long extra = n;
        long lastSpecial = n;
        long[] cannotChange = new long[n];
        boolean hadChange = false;
        long maxDifference = 0;

        for (int i = n - 1; i >= 0; --i) {
            if (previousGreaterEqual[i] != -1) {
                minK = Math.max(minK, arr[(int) previousGreaterEqual[i]] - arr[i]);
