def counting_pairs(n):
    return (n*(n-1))//2


def max_pairs(array):
    freq = {}
    zero_count = 0

    for num in array:
        if num == 0:
            zero_count += 1

        else:
            if num not in freq:
                freq[num] = 1
            else:
                freq[num] += 1

    total_pairs = 0
    max_freq = 0

    for count in freq.values():
        total_pairs += counting_pairs(count)
        if count > max_freq:
            max_freq = count

    if zero_count > 0:
        # If there are zeros, replace them with the most frequent number
        total_pairs += counting_pairs(max_freq + zero_count) - counting_pairs(max_freq)

    return total_pairs






