import java.util.Scanner;

class Main {

    static final int MOD = 998244353;

    // Fast exponentiation: computes x^y % MOD
    static long powerMod(long x, long y) {
        long res = 1;
        x %= MOD;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = res * x % MOD;
            }
            x = x * x % MOD;
            y >>= 1;
        }
        return res;
    }

