import java.util.*;

class Codechef {
 public static void main(String args[]) {
  Scanner sc = new Scanner(System.in);
  int t = sc.nextInt();
  while (t-- > 0) {
   int n = sc.nextInt(), q = sc.nextInt(), a[] = new int[n];
   long pre[] = new long[n];
   for (int i = 0; i < n; i++) {
    a[i] = sc.nextInt();
    if (i > 0) {
     pre[i] = pre[i - 1] + Math.abs(a[i] - a[i - 1]);
    }
   }
   for (int i = 0; i < q; i++) {
    int l = sc.nextInt(), r = sc.nextInt(), k = sc.nextInt();
    long abdf = 0; // absolute difference
    // for (int j = l; j < r; j++) {
    // abdf += Math.abs(a[j] - a[j - 1]);
    // }
    abdf = pre[r - 1] - pre[l - 1];
    long ghtao = Math.max(0, abdf - k);// bas itna hi ghatana hai
    long df = Math.abs(a[r - 1] - a[l - 1]); // difference b/w first and last element
    long middf = abdf - df; // middle difference
    long min = Math.min(middf, ghtao);
    long ans = (min + 1) / 2;// middle difference wale element 1 operation me 2 ghatayenge.
    ghtao -= min;
    ans += ghtao; // side elements 1 operation me 1 hi ghatayenge
    System.out.println(ans);

   }

  }
 }
}

