import sys
sys.setrecursionlimit(10**6)

def solve(i, j, skip, s, t, n, m, dp):
    if j == m:
        if i == n:
            return 0
        return 1
    if i == n:
        if j == m:
            return 0
        return 100000
    if dp[i][j][skip] != -1:
        return dp[i][j][skip]

    answer = float('inf')
    if s[i] == t[j]:
        answer = min(answer, solve(i + 1, j + 1, 0, s, t, n, m, dp))

    if skip:
        answer = min(answer, solve(i + 1, j, 1, s, t, n, m, dp))

    answer = min(answer, 1 + solve(i + 1, j, 1, s, t, n, m, dp))

    dp[i][j][skip] = answer
    return answer

