def count_triplets(A, N):
    cnt = n #for i=j=k cases n triplets exist

    for i in range(N):
        for k in range(i+1,min(i+102,N)): #going only in the forward direction hence every time count is incremented it is multiplied by 2

            #since the maximum difference between any two numbers is 100 if the distance
            #between them is greater than 100, they cannot be equated by any means .

            val=abs(A[k]-A[i])

            #compare the value with distance between them
                #if equal, for all the values of j between i and k the triplet is possible
            if val==(k-i):
                cnt+=((k-i+1)*2)

                #if value is greater than distance, they can be made equal by incrementing the distance by considering k to be outside the [i,k] interval

            elif val>(k-i):

                #k is possible only when the difference is even because everytime u select an element outside the interval the difference decreases by a multiple of 2 since we are using it in both |i-j| and |j-k|
                difference=val-(k-i)

                if (difference)%2==0:
                    if i-(difference//2)>=0:
                        cnt+=(1*2)
                    if k+(difference//2)<=(n-1):
                        cnt+=(1*2)
    return cnt

