import java.util.Scanner;

 class MinInversions {

    private static final long MOD = 998244353;

    // Function to count inversions in the binary string
    private static long findInversions(String s) {
        long n = s.length();
        long count = 0;
        long inversions = 0;

        for (int i = 0; i < n; ++i) {
            if (s.charAt(i) == '1') {
                ++count;
            } else {
                inversions += count;
            }
        }

        return inversions;
    }

    // Function to flip characters in the string based on counts a and b
    private static String flipCharacters(long a, long b, String s) {
        long aCount = 0;
        long bCount = 0;
        int n = s.length();
        char[] charArray = s.toCharArray();

        // Flip '0' to '1' from the end of the string
        for (int i = n - 1; i >= 0 && bCount < b; --i) {
            if (charArray[i] == '0') {
                charArray[i] = '1';
                ++bCount;
            }
        }

        // Flip '1' to '0' from the start of the string
        for (int i = 0; i < n && aCount < a; ++i) {
            if (charArray[i] == '1') {
                charArray[i] = '0';
                ++aCount;
            }
        }

        return new String(charArray);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            long n = scanner.nextLong();
            long k = scanner.nextLong();
            String s = scanner.next();
            long ans = Long.MAX_VALUE;

            // Try all possible splits of flips between a and b
            for (int i = 0; i <= k; ++i) {
                long a = i;
                long b = k - i;

                String currentString = flipCharacters(a, b, s);
                long currentInversions = findInversions(currentString);

                ans = Math.min(ans, currentInversions);
            }

            System.out.println(ans);
        }

        scanner.close();
    }
}

