    public static long modularMultiplication(long a, long b) {
        return (a % MOD_VALUE * b % MOD_VALUE) % MOD_VALUE;
    }

    // Modular addition to compute (a + b) % MOD_VALUE
    public static long modularAddition(long a, long b) {
        return (a % MOD_VALUE + b % MOD_VALUE) % MOD_VALUE;
    }

