        while (testCases-- > 0) {
            int arraySize = Integer.parseInt(reader.readLine()); // Read size of array (n)
            int fullArraySize = 2 * arraySize; // Full size of the array, which is 2 * n
            String[] inputArray = reader.readLine().split(" "); // Read the array input

