class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc=new Scanner(System.in);
		int t=sc.nextInt();
		while(t-->0)
		{
		    int n=sc.nextInt();
		    Pair arr[]=new Pair[n];
		    for(int i=0;i<n;i++)
		    arr[i]=new Pair(sc.nextInt(),sc.nextInt());
		    Arrays.sort(arr,(a,b)->(a.x-b.x));
		    ArrayList<Integer> al=new ArrayList<>();
		    al.add(arr[0].y);
		    for(int i=1;i<n;i++)
		    {
		        if(al.get(al.size()-1)<arr[i].y) al.add(arr[i].y);
		        else{
		            int d=bin(al,arr[i].y);
		            al.set(d,arr[i].y);
		        }
		    }
		    System.out.println(al.size());
		}

	}
	public static int bin(ArrayList<Integer> al,int val)
	{
	    int low=0,high=al.size()-1,ans=-1;
	    while(low<=high)
	    {
	        int mid=(low+high)/2;
	        if(al.get(mid)<=val){
	            ans=mid;low=mid+1;
	        }else high=mid-1;
	    }
	    return ans+1;
	}
}
class Pair
{
    int x,y;
    Pair(int x,int y)
    {
        this.x=x;
        this.y=y;
    }
}

