from math import log, floor

def checkPossibility(l, pointer, k):
    nd, d, options, counter= 0, 0, [], 0
    for i in l:
        count, temp= 0, i
        while(temp%k == 0):
            count, temp= count+1, temp//k
        if(i < pointer+1 and count == 0 and i*k >= pointer+1):
            nd= nd+1
        elif(i < pointer+1 and count > 0):
            d= d+count
        elif(i >= pointer+1 and count>0):
            d, counter= d+floor(log(i/(pointer+1), k)), counter+1
            options.append(count - floor(log(i/(pointer+1), k)))
        elif(i>= pointer+1 and count ==0):
            counter= counter+1
    # print(pointer+1, counter, nd, d, options)
    if(counter >= pointer+1):
        return True
    options.sort()
    counter, nd= counter+min(nd, d), max(nd-d, 0)
    while(len(options) and nd>1 and counter < pointer+1):
        temp= options.pop()
        if(temp != 0):
            nd, counter= max(nd-temp, 0), counter+min(temp-1, nd-1)
    return True if counter >= pointer+1 else False

for _ in range(int(input())):
    n, k= map(int, input().split())
    l= list(map(int, input().split()))
    ans, high, low, mid= 1, n-1, 0, 1
    while(high >= low):
        mid= (high + low)//2
        status = checkPossibility(l, mid, k)
        #print(status, mid+1)
        if(not status):
            high= mid - 1
        else:
            low, ans= mid + 1, mid + 1
    print(ans)

