        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        String[] input = br.readLine().trim().split("\\s+");

        int T = Integer.parseInt(input[0]);
        while (T-- > 0) {
            solve(br, out);
        }
        out.close();
    }

    static void solve(BufferedReader br, PrintWriter out) throws IOException {
        int n = Integer.parseInt(br.readLine().trim());
        long[] a = new long[n];
        String[] input = br.readLine().trim().split("\\s+");

        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(input[i]);
        }

        Arrays.sort(a);
        reverse(a);

        long[] f = new long[n + 1];
        for (long i : a) {
            f[(int) i]++;
        }

        long res = 1;
        long cnt = 0;
        for (int i = n; i >= 1; i--) {
            if (f[i] == 2) {
                cnt++;
                res = (res << 1) % MOD;
                continue;
            }
            if (f[i] == 1) {
                res = ((((res << 1) % MOD) * cnt) % MOD + res) % MOD;
                continue;
            }
            res = (((res * cnt) % MOD) * cnt) % MOD;
            cnt--;
        }
        out.println(res);
    }

    static void reverse(long[] array) {
        int left = 0, right = array.length - 1;
        while (left < right) {
            long temp = array[left];
            array[left] = array[right];
            array[right] = temp;
            left++;
            right--;
        }
    }
}

