            pref = suff = total = 0;
            isInc = false;
        }
    }

    static int[] v;
    static Data[] st;

    // Join two data structures
    static Data join(Data a, Data b) {
        Data result = new Data();
        result.pref = a.pref;
        result.suff = b.suff;
        result.total = a.total + b.total;
        if (a.isInc && b.isInc && a.last < b.first) {
            result.isInc = true;
        } else {
            result.isInc = false;
        }
        if (a.isInc && a.last < b.first) {
            result.pref += b.pref;
        }
        if (b.isInc && a.last < b.first) {
            result.suff += a.suff;
        }
        if (a.last < b.first) {
            int len = a.suff + b.pref;
            result.total -= (a.suff * (a.suff + 1)) / 2;
            result.total -= (b.pref * (b.pref + 1)) / 2;
            result.total += (len * (len + 1)) / 2;
        }
        result.first = a.first;
        result.last = b.last;
        return result;
    }

    // Build the segment tree
    static void build(int node, int l, int r) {
        if (l == r) {
            st[node].pref = 1;
            st[node].isInc = true;
            st[node].suff = 1;
            st[node].total = 1;
            st[node].first = v[l];
            st[node].last = v[l];
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        st[node] = join(st[2 * node], st[2 * node + 1]);
    }

    // Update the segment tree
    static void update(int node, int l, int r, int pos, int val) {
        if (l == r && l == pos) {
            st[node].pref = 1;
            st[node].isInc = true;
            st[node].suff = 1;
            st[node].total = 1;
            st[node].first = val;
            st[node].last = val;
            return;
        }
        int mid = (l + r) / 2;
        if (pos <= mid) {
            update(2 * node, l, mid, pos, val);
        } else {
            update(2 * node + 1, mid + 1, r, pos, val);
        }
        st[node] = join(st[2 * node], st[2 * node + 1]);
    }
      static int runCase(int n) {
        build(1, 0, n - 1);
