      for _ in range(cc):
        dp[u].append([0,inf])
      ndp = [[0,inf] for i in range(c + cc + 1)]
      for c in range(sub[u] + 1):
        for cc in range(1,sub[v] + 1):
          ccc = dp[u][c][0] * dp[v][cc][0] % mod
          n = dp[u][c][1] + dp[v][cc][1]
          if ndp[c + cc][1] < n:
