        int optimalGroup = 1;

        for (int k = 2; k <= n; k++) {
            if (n % k == 0) {
                double current = n / k + n * (1 - Math.pow(1 - p, k));
                if (mean > current) {
                    optimalGroup = k;
                    mean = current;
                }
            }
        }
        System.out.println(optimalGroup);
    }
}

