        ans += abs(d[0][1])
        d.append((d[0][0] + K, d[0][1]))
        d.popleft()
    if s[i] != t[i]:
        dif = 1 if s[i] == "1" else -1
        if len(d) == 0 or abs(d[0][1] + dif) > abs(d[0][1]):  
            if not (len(d) > 0 and d[0][0] == i):
                d.appendleft((i, 0))
            d[0] = d[0][0], d[0][1] + dif
        else:  
            d[0] = d[0][0], d[0][1] + dif
            if d[0][1] == 0:
                d.popleft()
print(ans)

def to_reduced_list(s):

    l = []
    for c in s:
        c = int(c)
        if len(l) > 0 and l[-1] == c:
            continue
        l.append(c)
    return l

def solve():
    N, P = map(int, input().split())
    tubes = [to_reduced_list(input()) for _ in range(2)]
    tubes.append([])
    if tubes[0][0] == tubes[1][0]:  
        tubes[0].insert(0, tubes[0][0] ^ 3)
    ans = len(tubes[0]) + len(tubes[1]) - 2
    if ans > 1:
        ans += 1
    print(ans)
    if P == 1:
        return
    moves = []
    def move(src, dst):
        moves.append((src, dst))
        if len(tubes[dst]) == 0 or tubes[dst][-1] != tubes[src][-1]:
            tubes[dst].append(tubes[src][-1])
        tubes[src].pop()
    if tubes[0][-1] == tubes[1][-1]:  
        if len(tubes[0]) > len(tubes[1]):
            move(0, 1)
        else:
            move(1, 0)
    for i in range(2):
        if len(tubes[i]) > 1:
            move(i, 2)  
            idx_to_empty = 0  
            if tubes[idx_to_empty][0] == tubes[2][0]:
                idx_to_empty ^= 1
            while len(tubes[idx_to_empty]) > 1:
                if tubes[idx_to_empty][-1] == tubes[2][0]:
                    move(idx_to_empty, 2)
                else:
                    move(idx_to_empty, idx_to_empty ^ 1)
            idx_to_empty ^= 1  
            while len(tubes[idx_to_empty]) > 1:
                if tubes[idx_to_empty][-1] == tubes[2][0]:
                    move(idx_to_empty, 2)
                else:
                    move(idx_to_empty, idx_to_empty ^ 1)
            move(2, idx_to_empty)  
            break
    assert len(moves) == ans
    for a, b in moves:
        print(1 + a, 1 + b)

T = int(input())
