def zys(n, b):
    a = [0] * (n + 1)
    count = 0
    
    for i in range(2, n + 1):
        if not a[i]:
            for j in range(i, n + 1, i):
                a[j] = i
    for i in range(1, n + 1):
        if a[i] <= b:
            count += 1
    return count

