public class Main {
	public static boolean leap(int year) {
		return year%400==0||(year%4==0&&year%100!=0);
	}
	public static int maxdays(int year,int month) {
		if(month==1||month==3||month==5||month==7||month==8||month==10||month==12) return 31;
		if(month==4||month==6||month==9||month==11)return 30;
		return leap(year)?29:28;
	}
	public static void main(String[] args) {
		int [] arr = {13,1,2,3,5,4,4,2,2,2};
		int count=0;
		int year=2000,month=1,day=1;
		while(true){
			if(year==2024&&month==4&&day==14)break;
			int sum=0;
			sum=sum+arr[year/1000]+arr[year/100%10]+arr[year/10%10]+arr[year%10];
			sum=sum+arr[month/10]+arr[month%10];
			sum=sum+arr[day/10]+arr[day%10];
			if(sum>50)count++;
			if(day<maxdays(year,month))day++;
			else {
				day=1;
				if(month<12)month++;
				else {
					year++;
					month=1;
				}
			}
		}
		System.out.print(count);

	}
}

