def cal_front_len(string):
    size = 0
    for i in range(len(string)):
        if string[i] in "lqb":
            size += 1
        else :
            break
    return size

def cal_back_len(string):
    size = 0
    for i in range( len(string)-1, -1, -1):
        if string[i] in "lqb":
            size += 1
        else :
            break
    return size

def is_valid(string):
    len_all = len( string )
    len_front = cal_front_len(string)
    len_back = cal_back_len(string)

    if len_front ==  len_all:
        return True
    if len_front > len_back :
        return False
    if len_front <= len_back:

        left = 0

        right = len_all - len_back + len_front - 1
        while left < right :
            if string[left] != string[right]:
                return False
            left += 1
            right -= 1
        return True
        


