import java.util.Scanner;

public class Main {
    public static long computeMaxScore(int n, int[] A, int m, String S) {
        long[] dp = new long[m + 1];
        int[] match = new int[m + 1];


        for(int i = 3; i <= m; i++) {
            String substr = S.substring(i - 3, i);
            if(substr.equals("abc")) {
                match[i] = match[i - 3] + 1;
            } else {
                match[i] = 0;
            }
        }


        for(int i = 1; i <= m; i++) {

            dp[i] = dp[i - 1];
            

            if(match[i] > 0) {
                int max_k = Math.min(match[i], n);
                for(int k = 1; k <= max_k; k++) {
                    if(i >= 3 * k) {
                        dp[i] = Math.max(dp[i], dp[i - 3 * k] + A[k - 1]);
                    }
                }
            }
        }

        return dp[m];
    }

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] A = new int[n];
        for(int i = 0; i < n; i++) {
            A[i] = sc.nextInt();
        }
        int m = sc.nextInt();
        String S = sc.next();
        sc.close();
        long result = computeMaxScore(n, A, m, S);
        System.out.println(result);
    }
}

