    static PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out)); 

    public static void main(String[] args) throws IOException {
     Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(); 
        int m = sc.nextInt(); 
        int q = sc.nextInt(); 


        PriorityQueue<long[]> pq = new PriorityQueue<>((o1, o2) -> Long.compare(o1[1], o2[1]));


        List<int[]>[] list = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) list[i] = new ArrayList<>();


        long[][] map = new long[n + 1][n + 1];
        for (long[] v : map) Arrays.fill(v, Long.MAX_VALUE);


        int a, b;
        for (int i = 0; i < m; i++) {

            a = sc.nextInt();;
            b = sc.nextInt();;
            list[a].add(new int[]{b, 1});
            list[b].add(new int[]{a, 1});
        }


        for (int i = 1; i <= n; i++) {
            map[i][i] = 0L;
            pq.add(new long[]{i, 0L});
            while (!pq.isEmpty()) {
                long[] v = pq.poll();
                for (int[] x : list[(int) v[0]]) {
                    if (v[1] + x[1] < map[i][x[0]]) {
                        map[i][x[0]] = v[1] + x[1];
                        pq.add(new long[]{x[0], map[i][x[0]]});
                    }
                }
            }
        }


        long sum = 0L;
        for (int k = 0; k < q; k++) {

            a = sc.nextInt();;
            b = sc.nextInt();;
            for (int i = 1; i <= n; i++) {
                if (map[a][i] <= b) sum++;
            }
        }


        out.printf("%.2f", 1.0 * sum / q);
        out.flush();
    }
}

