N = int(1e6 + 5)
left = [0 for _ in range(N)]
right = [0 for _ in range(N)]

n, m = [int(i) for i in input().split()]
lst = [int(i) for i in input().split()]

for i in lst:
    if i < 0:
        left[-i] += 1
    else:
        right[i] += 1
for i in range(N - 1):
    left[i + 1] += left[i]
    right[i + 1] += right[i]

max_measure = 0
for i in lst:
    measure = 0
    if i < 0:
        s = -i
        residue = m - s
        if residue <= 0:
            continue
        measure += left[s]
        residue -= s
        if residue > 0:
            measure += right[min(residue, N - 1)]
    else:
        s = i
        residue = m - s
        if residue <= 0:
            continue
        measure += right[s]
        residue -= s
        if residue > 0:
            measure += left[min(residue, N - 1)]
    if measure > max_measure:
        max_measure = measure
print(max_measure)

import java.util.Scanner;


public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] l=new int[2*(int)Math.pow(10,6)+5];
        int[] r=new int[2*(int)Math.pow(10,6)+5];
        int count=0;
        int max=0;
        for (int i=1;i<=n;i++){
            int a= sc.nextInt();
            if (a<0) l[-a]++;
            else if (a>0) r[a]++;
            else count++;
        }
        for(int i=1;i<=m;i++){
            l[i]+=l[i-1];
            r[i]+=r[i-1];
        }
        for (int i=1;i<=m;i++){
            int b=l[i];
            if(m-i*2>0){
                b+=r[m-i*2];
            }
            max=Math.max(max,b);
            b=r[i];
            if(m-i*2>0){
                b+=l[m-i*2];
            }
            max=Math.max(max,b);
        }
        System.out.println(max+count);
        sc.close();
    }
}

