            bw.write(ans1+" "+(m-ans2)+"\n");
        }
        bw.flush();
    }
    static int find(int p[],double pos){
        if(p[0]>pos){
            return -1;
        }
        if(p[p.length-1]<=pos){
            return p.length-1;
        }
        int l=0,r=p.length-1;
        while(l<r){
            int mid=(l+r)>>1;
            if(p[mid]<=pos){
                l=mid;
            }
            else{
                r=mid-1;
            }
            if(l==r-1){
                if(p[r]<=pos){
                    l=r;
                }
                break;
            }
        }
        return l;
