        int n = sc.nextInt();
        long s = sc.nextLong();


        long[] p = new long[n + 1];
        long[] c = new long[n + 1];
        long[] cnt = new long[1000001]; 
        long Sum = 0, now = 0, ans = 0;


        for (int i = 1; i <= n; i++) {
            p[i] = sc.nextLong();
            c[i] = sc.nextLong();
            cnt[(int) c[i]] += p[i];
            now += p[i];
            Sum += p[i] * c[i];
        }


        for (int i = 1; i <= 1000000; i++) {
            if (now < s) {
                break;
            }
            ans += s;
            Sum -= now;
            now -= cnt[i];
        }


        System.out.println(ans + Sum);

        sc.close();
    }
