def main():
    import sys
    import numpy as np


    input = sys.stdin.read().split()
    n = int(input[0])
    H = list(map(int, input[1:n+1]))
    

    H_sorted = sorted(H)
    

    max_H = H_sorted[-1]
    

    freq = np.zeros(max_H +1, dtype=int)
    for h in H_sorted:
        freq[h] +=1
    

    multiples_count = np.zeros(max_H +1, dtype=int)
    

    for g in range(1, max_H+1):
        multiples_count[g] = freq[g::g].sum()
    

    for g in range(max_H, 0, -1):
        if multiples_count[g] >=3:

            list_multiples = []
            for h in H_sorted:
                if h % g ==0:
                    list_multiples.append(h)
                    if len(list_multiples) ==3:
                        break
            if len(list_multiples) >=3:
                print(' '.join(map(str, list_multiples)))
                break

if __name__ == "__main__":
