import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main {


    public static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }


    public static int gcdThree(int a, int b, int c) {
        return gcd(gcd(a, b), c);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int[] h = new int[n];
        for (int i = 0; i < n; i++) {
            h[i] = scanner.nextInt();
        }


        Arrays.sort(h);
        int maxnum = h[n - 1];

        ArrayList<ArrayList<Integer>> fac = new ArrayList<>();
        for (int i = 0; i <= maxnum+1; i++) {
            fac.add(new ArrayList<>());
        }


        for (int i = 0; i < n; i++) {
            for (int j = 1; j * j <= h[i]; j++) {
                if (h[i] % j == 0) {
                    fac.get(j).add(h[i]);
                    if (h[i] / j!= j) {
                        fac.get(h[i] / j).add(h[i]);
                    }
                }
            }
        }


        for (int i = maxnum+1; i >= 1; i--) {
            ArrayList<Integer> currentFac = fac.get(i);
            if (currentFac.size() >= 3) {
                int a = currentFac.get(0);
                int b = currentFac.get(1);
                int c = currentFac.get(2);
                if (gcdThree(a, b, c) == i) {
                    System.out.println(a + " " + b + " " + c);
                    return;
                }
            }
        }
    }
}

